/* Tompkins-Cortland labor timeline data. Every event lists its sources; archive links point to items in ../tclc/. */
window.LABOR_TIMELINE = {"eras":[{"key":"roots","name":"Before the Coalition","span":"1979–1983","blurb":"Cornell service workers win a union and Ithaca gets its largest local."},{"key":"founding","name":"A coalition of locals","span":"1984–1987","blurb":"Two dozen unions start meeting, hold the first Labor Day rally, fight for a plant-closing law, and back the Cargill miners."},{"key":"coalition","name":"Staff, safety, and Smith Corona","span":"1988–1993","blurb":"The Coalition hires staff, runs a state-funded health and safety program, investigates Smith Corona, grows to four counties, and votes to join the AFL-CIO."},{"key":"council","name":"The Midstate Central Labor Council","span":"1994–2002","blurb":"Chartered by the AFL-CIO, the council opens a Cortland office, starts a Workers Rights Board, and helps seed the living wage movement."},{"key":"center","name":"From living wage coalition to Workers’ Center","span":"2003–2008","blurb":"The Living Wage Coalition opens a hotline, wins back wages, certifies living wage employers, and takes the name Tompkins County Workers’ Center."},{"key":"community","name":"The community union","span":"2009–2014","blurb":"The Workers’ Center affiliates with the AFL-CIO, takes on Regis, backs new unions, and wins a living wage for county contract workers."},{"key":"county","name":"A living wage for the whole county","span":"2015–2019","blurb":"Campaigns for a countywide minimum wage, new unions at Gimme! Coffee and Ithaca College, and a Troublemakers School."},{"key":"now","name":"Pandemic and new campaigns","span":"2020–2026","blurb":"Relief for excluded workers, a just cause campaign in the City of Ithaca, and a county minimum wage study."}],"themes":{"founding":"Founding and governance","strikes":"Strikes and picket lines","organizing":"Organizing","contracts":"Contracts and bargaining","wages":"Living wage and minimum wage","closings":"Plant closings and jobs","safety":"Health and safety","rights":"Wage theft and workers’ rights","politics":"Politics and law","laborday":"Labor Day picnic and awards","press":"Labor press","solidarity":"Solidarity beyond the county"},"orgs":{"tclc":"Labor Coalition / Midstate CLC","tcwc":"Workers’ Center and Living Wage Coalition","uaw2300":"UAW Local 2300","trades":"Building trades","public":"Public-sector unions (CSEA, NYSUT, UUP, APWU)","private":"Private-sector unions (IAM, UAW, Teamsters, SEIU)","students":"Students and Cornell/IC","gov":"City and county government"},"events":[{"id":"cornell-service-union","date":"1981","sort":"1981-06-30","year":1981,"label":"1981","era":"roots","title":"Cornell service workers win a union with the UAW","summary":"Food service, custodial and maintenance workers at Cornell vote in the UAW. Their local, 2300, becomes the largest union in Tompkins County.","body":["Before the union, raises at Cornell were handed out under what management called merit. Cathy Valentino later recalled that some workers got a raise and others got nothing. Workers formed a group called Active Concerned Employees and chose the UAW to help them organize.","Local 2300 went on to represent workers well beyond the campus, including the Ithaca Housing Authority, the Ithaca Times, the Holiday Inn and, later, Cornell graduate students. A 1986 Working Press article dates the union’s gains at Cornell from 1980, and Valentino’s 2014 account gives 1981."],"themes":["organizing","contracts"],"orgs":["uaw2300","students"],"sources":[{"k":"paper","label":"The Workers’ Edge, Spring 2014","sub":"Newsletter of the Tompkins County Workers’ Center","href":null},{"k":"paper","label":"The Working Press, Vol. 1 No. 2, Labor Day 1986","sub":"Read it in the Working Press collection","href":"../../working-press/"}],"thumb":"../../working-press/thumb/p0015b.jpg","note":"Sources give 1980 and 1981. The election date has not yet been checked against the NLRB record."},{"id":"coalition-roots-1982","date":"1982","sort":"1982-06-30","year":1982,"label":"1982","era":"roots","title":"Local unions begin joint campaigns","summary":"A 1996 council grant proposal dates the area’s joint union campaigns to 1982, two years before the Coalition formally organized.","body":["When the Midstate Central Labor Council asked the AFL-CIO for organizing money in 1996, it attached a history of its campaigns that starts in 1982. The formal coalition followed in 1984."],"themes":["founding"],"orgs":["tclc"],"sources":[{"k":"archive","label":"“A Comprehensive Organizing Program for South-Central New York”: grant proposal","sub":"Labor Coalition records · May 1996 · Proposal","href":"../tclc/items/tclc-0102/","id":"tclc-0102"}],"thumb":"../tclc/media/thumb/b1-330.webp","note":null},{"id":"hoffman-letter","date":"1984-02-24","sort":"1984-02-24","year":1984,"label":"February 24, 1984","era":"founding","title":"A dozen unions meet to explore a joint labor body","summary":"Jay Hoffman of Cornell’s ILR Extension writes to area unions after representatives of more than a dozen Ithaca and Cortland locals met to talk about working together.","body":["The unions named their needs, starting with a joint body for political action. Hoffman announced a second meeting for March 8 at Cornell’s Statler Inn."],"themes":["founding"],"orgs":["tclc","students"],"sources":[{"k":"archive","label":"Jay Hoffman, Cornell ILR Extension, to area unions on forming a joint labor body","sub":"Labor Coalition records · February 24, 1984 · Letter","href":"../tclc/items/tclc-0140/","id":"tclc-0140"}],"thumb":"../tclc/media/thumb/b36-044.webp","note":null},{"id":"joint-labor-coalition","date":"1984-04-05","sort":"1984-04-05","year":1984,"label":"April 5, 1984","era":"founding","title":"The Tompkins-Cortland Joint Labor Coalition approves its structure","summary":"Members debate whether groups outside unions, such as the Unemployed Councils, can join, and approve the proposed structure.","body":["Acting chair Susan Schlaepfer restated the coalition’s objectives. The minutes also set meeting dates and plans for a workshop on political action, held April 14."],"themes":["founding"],"orgs":["tclc"],"sources":[{"k":"archive","label":"Minutes of the April 5 meeting, Tompkins-Cortland Joint Labor Coalition","sub":"Labor Coalition records · April 5, [1984] · Minutes","href":"../tclc/items/tclc-0141/","id":"tclc-0141"},{"k":"archive","label":"“Political Action and Education in 1984”: workshop program","sub":"Labor Coalition records · April 14, 1984 · Flyer","href":"../tclc/items/tclc-0142/","id":"tclc-0142"},{"k":"archive","label":"Approved organizational structure","sub":"Labor Coalition records · [May 1984] · Constitution or rules","href":"../tclc/items/tclc-0146/","id":"tclc-0146"}],"thumb":"../tclc/media/thumb/b36-046.webp","note":null},{"id":"first-officers","date":"1984-06-05","sort":"1984-06-05","year":1984,"label":"June 5, 1984","era":"founding","title":"The coalition elects its first officers","summary":"Meeting at Tompkins Cortland Community College, the coalition chooses Jim Morrissette of the Cornell Security Employees Union as chair.","body":["Tom Keane of CSEA-TC3 became vice chair, Skye Milliman of Painters Local 178 secretary, and Jim Nichols of the TC3 Faculty Association treasurer. The press release counted more than twenty unions representing nearly 6,000 workers.","At the May 7 meeting before it, members had elected a first steering committee and passed a resolution to patronize union businesses."],"themes":["founding"],"orgs":["tclc","public"],"sources":[{"k":"archive","label":"Press release: the coalition elects its first officers","sub":"Labor Coalition records · June 5, 1984 · Press release","href":"../tclc/items/tclc-0147/","id":"tclc-0147"},{"k":"archive","label":"Minutes of the May 7, 1984 meeting","sub":"Labor Coalition records · May 7, 1984 · Minutes","href":"../tclc/items/tclc-0145/","id":"tclc-0145"},{"k":"archive","label":"Agenda for the June 5, 1984 meeting at TC3","sub":"Labor Coalition records · June 5, 1984 · Agenda","href":"../tclc/items/tclc-0148/","id":"tclc-0148"}],"thumb":"../tclc/media/thumb/b36-053.webp","note":null},{"id":"ithaca-journal-contract","date":"1984","sort":"1984-06-30","year":1984,"label":"1984","era":"founding","title":"Backing the Ithaca Journal unit","summary":"The coalition circulates a fact sheet on how the Ithaca Journal treated its employees, who had been without a contract since November.","body":["Members were asked to spread the word and support the International Typographical Union unit at the paper."],"themes":["contracts"],"orgs":["tclc"],"sources":[{"k":"archive","label":"Letter to members on the Ithaca Journal unit's fight for a contract","sub":"Labor Coalition records · [1984] · Letter","href":"../tclc/items/tclc-0143/","id":"tclc-0143"}],"thumb":"../tclc/media/thumb/b36-048.webp","note":null},{"id":"first-labor-day","date":"1984-09-03","sort":"1984-09-03","year":1984,"label":"September 3, 1984","era":"founding","title":"The first Labor Day rally and picnic at Stewart Park","summary":"The coalition holds its first Labor Day celebration at Stewart Park after the city at first refuses permission for sound amplification.","body":["Chair Jim Morrissette asked Mayor John Gutenberger for help with the permit in July and said he would appeal to the Board of Public Works. At the August meeting the mayor spoke about unions joining in one voice.","The picnic became an annual event. Union City News called the 2002 picnic the 19th and the Workers’ Edge called 2012 the 29th, both counting from 1984."],"themes":["laborday","founding"],"orgs":["tclc","gov"],"sources":[{"k":"archive","label":"Jim Morrissette to Mayor John Gutenberger on the first Labor Day rally","sub":"Labor Coalition records · July 26, 1984 · Letter","href":"../tclc/items/tclc-0151/","id":"tclc-0151"},{"k":"archive","label":"Minutes of the August 2, 1984 meeting","sub":"Labor Coalition records · August 2, 1984 · Minutes","href":"../tclc/items/tclc-0153/","id":"tclc-0153"},{"k":"archive","label":"Union City News, Midstate Central Labor Council, September 2002","sub":"Labor Coalition records · September 2002 · Newsletter","href":"../tclc/items/tclc-0022/","id":"tclc-0022"}],"thumb":"../tclc/media/thumb/b36-057.webp","note":null},{"id":"officials-meeting","date":"1984-11-13","sort":"1984-11-13","year":1984,"label":"November 13, 1984","era":"founding","title":"Twenty-six unions sit down with city and county officials","summary":"The coalition, now \"twenty-six unions with over 7000 members,\" invites Ithaca and Tompkins County officials to meet labor leaders informally.","body":["The handwritten sign-in sheet survives with the names of union officers and officials who came."],"themes":["politics"],"orgs":["tclc","gov"],"sources":[{"k":"archive","label":"Invitation to city and county officials, November 13, 1984, with the sign-in sheet","sub":"Labor Coalition records · November 13, 1984 · Meeting notice","href":"../tclc/items/tclc-0158/","id":"tclc-0158"},{"k":"archive","label":"Jim Morrissette thanks participants in the November 13 meeting","sub":"Labor Coalition records · November 18, 1984 · Letter","href":"../tclc/items/tclc-0159/","id":"tclc-0159"}],"thumb":"../tclc/media/thumb/b36-066.webp","note":null},{"id":"plant-closing-principles","date":"1984-12","sort":"1984-12-15","year":1984,"label":"December 1984","era":"founding","title":"Principles for a plant-closing law","summary":"The coalition approves a statement of principles on plant-closing legislation and adopts its first dues structure.","body":["Dues for 1985 were set at $30 for locals of up to 49 members, $60 for 50 to 100, and $100 for larger locals. The plant-closing principles started a campaign that ran through 1987."],"themes":["closings","founding"],"orgs":["tclc"],"sources":[{"k":"archive","label":"New Year letter on the plant closing principles","sub":"Labor Coalition records · [January 1985] · Letter","href":"../tclc/items/tclc-0167/","id":"tclc-0167"},{"k":"archive","label":"Treasurer's letter on the new 1985 dues structure","sub":"Labor Coalition records · [December 1984] · Letter","href":"../tclc/items/tclc-0165/","id":"tclc-0165"}],"thumb":"../tclc/media/thumb/b36-096.webp","note":null},{"id":"advance-notice-bill","date":"1985-04-23","sort":"1985-04-23","year":1985,"label":"April 1985","era":"founding","title":"\"Advance Notice Legislation\" goes to Common Council","summary":"The coalition drafts an Ithaca ordinance requiring advance notice of plant closings and major layoffs.","body":["The proposal had three parts: notice to workers and the city before a closing or large layoff, city reports and investigations of possible closings, and a voluntary code for responsible employers. Ithaca business people opposed it. Religious and social service groups wrote in support.","Looking back on its first full year, the coalition listed the bill, the Labor Day rally, a labor movie series, support for striking teachers, a photo exhibit and voter registration."],"themes":["closings","politics"],"orgs":["tclc","gov"],"sources":[{"k":"archive","label":"“Advance Notice Legislation: A Summary”","sub":"Labor Coalition records · April 23, 1985 · Proposal","href":"../tclc/items/tclc-0171/","id":"tclc-0171"},{"k":"archive","label":"Notice for the April 25 meeting, with a year of accomplishments","sub":"Labor Coalition records · April 25, [1985] · Meeting notice","href":"../tclc/items/tclc-0170/","id":"tclc-0170"},{"k":"archive","label":"Letter to all members: plant closing bill and a resolution on South Africa","sub":"Labor Coalition records · [May 1985] · Letter","href":"../tclc/items/tclc-0172/","id":"tclc-0172"},{"k":"archive","label":"Ithaca Monthly Meeting of Friends endorses the plant closing principles","sub":"Labor Coalition records · March 25, [year not given] · Letter","href":"../tclc/items/tclc-0192/","id":"tclc-0192"}],"thumb":"../tclc/media/thumb/b36-100.webp","note":null},{"id":"apartheid-resolution","date":"1985-05","sort":"1985-05-15","year":1985,"label":"Spring 1985","era":"founding","title":"A resolution against apartheid","summary":"Members pass a resolution against South African apartheid and call for divestment.","body":["The coalition’s Labor Movie of the Month that May was \"Amandla!\" Divestment from South Africa was also a live cause on the Cornell campus that year."],"themes":["solidarity"],"orgs":["tclc","students"],"sources":[{"k":"archive","label":"Letter to all members: plant closing bill and a resolution on South Africa","sub":"Labor Coalition records · [May 1985] · Letter","href":"../tclc/items/tclc-0172/","id":"tclc-0172"},{"k":"archive","label":"Labor Movie of the Month flyer: “Amandla!”","sub":"Labor Coalition records · May 23, [1985] · Flyer","href":"../tclc/items/tclc-0161/","id":"tclc-0161"}],"thumb":"../tclc/media/thumb/b36-101.webp","note":null},{"id":"uaw-2300-strike-1985","date":"1985-08-23","sort":"1985-08-23","year":1985,"label":"August 23, 1985","era":"founding","title":"\"Fighting Friday\": UAW Local 2300 strikes Cornell","summary":"Cornell service and maintenance workers strike for their third contract. Building trades honor the lines, and students and faculty join the pickets.","body":["The coalition had warned member unions in July that Local 2300 might strike and set up a strike support fund. The local’s newsletter described buses of strikers at 5 a.m., five thousand leaflets handed to arriving parents in an hour, and building tradespeople refusing to cross. The contract was negotiated, struck for, and ratified.","The bargaining team included Al Davidoff, Walt Smithers, Emily Apgar, Cathy Valentino, Leo LaMontain, Cindy Doolittle and Perry Huested."],"themes":["strikes","contracts"],"orgs":["uaw2300","trades","students"],"sources":[{"k":"paper","label":"UAW Local 2300, The Bear Facts, Labor Day 1985 (bound with The Working Press)","sub":"From the OCR transcription of the full run; page images not yet online","href":null},{"k":"archive","label":"Letter on UAW Local 2300's contract fight at Cornell","sub":"Labor Coalition records · July 19, 1985 · Letter","href":"../tclc/items/tclc-0174/","id":"tclc-0174"},{"k":"archive","label":"Jim Morrissette's letter to the editor on “Workers Against Unions” at Cornell","sub":"Labor Coalition records · May 30, 1985 · Letter","href":"../tclc/items/tclc-0173/","id":"tclc-0173"}],"thumb":"../tclc/media/thumb/b36-103.webp","note":null},{"id":"labor-day-1985","date":"1985-09-02","sort":"1985-09-02","year":1985,"label":"September 2, 1985","era":"founding","title":"Labor Day 1985: the Friend of Labor and the Goat of Labor","summary":"Congressman Matt McHugh and Mayor John Gutenberger speak at the second Labor Day rally, which hands out a Friend of Labor Award and names a Goat of Labor.","body":["The two awards, one honoring an ally and one shaming an anti-union employer or official, became the most reported part of the picnic for decades."],"themes":["laborday","politics"],"orgs":["tclc","gov"],"sources":[{"k":"archive","label":"Labor Day Celebration and Rally flyer, Monday, September 2","sub":"Labor Coalition records · Monday, September 2, [1985] · Flyer","href":"../tclc/items/tclc-0176/","id":"tclc-0176"}],"thumb":"../tclc/media/thumb/b36-105.webp","note":null},{"id":"third-year","date":"1985-12-17","sort":"1985-12-17","year":1985,"label":"December 1985","era":"founding","title":"Planning a labor newspaper","summary":"Starting its third year, the coalition proposes its own newspaper. A pilot issue is planned for spring 1986.","body":["A February 1986 gathering at Cornell’s ILR Conference Center, hosted by Al Davidoff and Tom Joyce, celebrated the anniversary and planned the paper. In April the coalition set a deadline for articles and asked the ILR School for student interns."],"themes":["press","founding"],"orgs":["tclc","students"],"sources":[{"k":"archive","label":"December 1985 letter: beginning the third year","sub":"Labor Coalition records · December 17, 1985 · Letter","href":"../tclc/items/tclc-0177/","id":"tclc-0177"},{"k":"archive","label":"February 1986 invitation to a gathering at Cornell's ILR Conference Center","sub":"Labor Coalition records · February 5, 1986 · Letter","href":"../tclc/items/tclc-0182/","id":"tclc-0182"},{"k":"archive","label":"Notice on student interns, the plant closing bill, and the labor newspaper","sub":"Labor Coalition records · [Spring 1986] · Meeting notice","href":"../tclc/items/tclc-0187/","id":"tclc-0187"}],"thumb":"../tclc/media/thumb/b36-107.webp","note":null},{"id":"cargill-strike-begins","date":"1986-04-02","sort":"1986-04-02","year":1986,"label":"April 2, 1986","era":"founding","title":"The Cargill salt miners strike in Lansing","summary":"About 140 members of the International Association of Machinists walk out at the Cargill salt mine in Lansing, over seniority, job classifications and a two-tier wage plan.","body":["On April 28 the miners voted 110 to 13 to keep striking. Cargill hired permanent replacements. \"It’s the power for us over our own lives,\" striker Frank Febus told the first Working Press.","It was, the paper said, the longest and most potentially militant strike in the Tompkins-Cortland area in many years."],"themes":["strikes"],"orgs":["private","tclc"],"sources":[{"k":"paper","label":"The Working Press, Vol. 1 No. 1, May 1986","sub":"Read it in the Working Press collection","href":"../../working-press/"}],"thumb":"../../working-press/thumb/p0004a.jpg","note":null},{"id":"working-press-launch","date":"1986-05","sort":"1986-05-15","year":1986,"label":"May 1986","era":"founding","title":"The Working Press, issue one","summary":"The coalition’s newspaper debuts with the Cargill strike on the front page and an editorial asking \"Why a Labor Paper?\"","body":["The editorial answered that organized labor represented 7,000 people in Tompkins and Cortland counties, in every sector from mines to classrooms. Joan Lockwood co-edited. Regular features included News from the Locals and The Inquiring Photographer.","The paper ran into the late 1990s. A 1997 plan proposed relaunching it as a regional paper for Southern Tier and Central New York unions."],"themes":["press"],"orgs":["tclc"],"sources":[{"k":"paper","label":"The Working Press, Vol. 1 No. 1, May 1986","sub":"Read it in the Working Press collection","href":"../../working-press/"},{"k":"archive","label":"“A Regional Working Press”: proposal and budget","sub":"Labor Coalition records · [1997] · Proposal","href":"../tclc/items/tclc-0081/","id":"tclc-0081"}],"thumb":"../../working-press/thumb/p0004a.jpg","note":null},{"id":"cargill-rally-may","date":"1986-05-17","sort":"1986-05-17","year":1986,"label":"May 17, 1986","era":"founding","title":"A rally for the Cargill miners on the Commons","summary":"The coalition gets a city permit for a rally in Bank Alley. Congressman Matthew McHugh sends a letter: \"I am very concerned about the situation at Cargill.\"","body":["McHugh noted the strike was in its eighth week and that Cargill had brought in permanent replacements, and urged both sides back to the table. Al Davidoff thanked him on May 20."],"themes":["strikes","politics"],"orgs":["tclc","gov"],"sources":[{"k":"archive","label":"City of Ithaca agreement and Commons permit for a Cargill support rally","sub":"Labor Coalition records · Issued May 13, 1986 (rally May 17) · Permit","href":"../tclc/items/tclc-0055/","id":"tclc-0055"},{"k":"archive","label":"Congressman Matthew McHugh to the rally: “I am very concerned about the situation at Cargill”","sub":"Labor Coalition records · May 17, 1986 · Letter","href":"../tclc/items/tclc-0056/","id":"tclc-0056"},{"k":"archive","label":"Al Davidoff to Congressman Matthew McHugh, thanking him for his letter","sub":"Labor Coalition records · May 20, 1986 · Letter","href":"../tclc/items/tclc-0054/","id":"tclc-0054"}],"thumb":"../tclc/media/thumb/b1-147.webp","note":null},{"id":"cargill-solidarity-committee","date":"1986-06-29","sort":"1986-06-29","year":1986,"label":"June–July 1986","era":"founding","title":"The Cargill Strikers’ Solidarity Committee","summary":"Supporters research the company, set a strategy, and rally again on July 26. Their pamphlet calls the strike \"a little conquest in Lansing.\"","body":["A June 24 proposal asked the committee to keep one goal, helping IAM Local 1607 win. By mid-August Painters 178, UAW 2300, the St. Joe zinc miners, Cornell faculty and the Ithaca Teachers Association had all sent people to the picket line. Moosewood restaurant helped feed strikers."],"themes":["strikes","solidarity"],"orgs":["tclc","private","students"],"sources":[{"k":"archive","label":"“A little conquest in Lansing”: Cargill Strikers' Solidarity Committee pamphlet","sub":"Labor Coalition records · June 29, 1986 · Pamphlet","href":"../tclc/items/tclc-0051/","id":"tclc-0051"},{"k":"archive","label":"“Proposal for discussion”: three strategy points for the Cargill solidarity campaign","sub":"Labor Coalition records · June 24, [1986] · Proposal","href":"../tclc/items/tclc-0053/","id":"tclc-0053"},{"k":"archive","label":"“Support the Cargill Workers” rally flyer, July 26","sub":"Labor Coalition records · July 26, [1986] · Flyer","href":"../tclc/items/tclc-0049/","id":"tclc-0049"},{"k":"archive","label":"Cargill Strikers Support Committee: report on union locals outreach","sub":"Labor Coalition records · August 15, 1986 · Report","href":"../tclc/items/tclc-0036/","id":"tclc-0036"}],"thumb":"../tclc/media/thumb/b1-142.webp","note":null},{"id":"cargill-sheriff","date":"1986-07-31","sort":"1986-07-31","year":1986,"label":"July 31, 1986","era":"founding","title":"Pickets, trucks and the sheriff","summary":"The coalition asks Sheriff Robert Howard to protect picketers on Portland Point Road and enforce the speed limit for salt trucks.","body":["The sheriff answered on August 1 that deputies would not take sides and that anyone who broke the law would be arrested."],"themes":["strikes"],"orgs":["tclc","gov"],"sources":[{"k":"archive","label":"Tom Joyce to Sheriff Robert Howard on the Cargill picket line","sub":"Labor Coalition records · July 31, 1986 · Letter","href":"../tclc/items/tclc-0045/","id":"tclc-0045"},{"k":"archive","label":"Sheriff Robert Howard's reply on policing the Cargill strike","sub":"Labor Coalition records · August 1, 1986 · Letter","href":"../tclc/items/tclc-0046/","id":"tclc-0046"}],"thumb":"../tclc/media/thumb/b1-133.webp","note":null},{"id":"cargill-nlrb","date":"1986-08-05","sort":"1986-08-05","year":1986,"label":"August 1986","era":"founding","title":"The NLRB rules against the strikers","summary":"The labor board finds the strike was over economic issues, not bad-faith bargaining, so Cargill does not have to rehire the miners.","body":["The coalition kept picketing. About 100 miners were still out. By Labor Day the 96 remaining strikers were starting their sixth month on the line, and a decertification petition was \"waiting in the wings.\""],"themes":["strikes","politics"],"orgs":["tclc","private"],"sources":[{"k":"archive","label":"Labor Coalition press release: NLRB rules against the striking Cargill miners","sub":"Labor Coalition records · August 5, 1986 · Press release","href":"../tclc/items/tclc-0042/","id":"tclc-0042"},{"k":"paper","label":"The Working Press, Vol. 1 No. 2, Labor Day 1986","sub":"Read it in the Working Press collection","href":"../../working-press/"}],"thumb":"../tclc/media/thumb/b1-112.webp","note":null},{"id":"labor-day-1986","date":"1986-09-01","sort":"1986-09-01","year":1986,"label":"September 1, 1986","era":"founding","title":"The third Labor Day picnic","summary":"Members of many unions, with friends and families, gather at Stewart Park for the coalition’s third annual picnic.","body":["The Labor Day issue of the Working Press ran under the banner \"Support the strikers\" and opened with Ronald Seeber’s history of Labor Day."],"themes":["laborday"],"orgs":["tclc"],"sources":[{"k":"paper","label":"The Working Press, Vol. 1 No. 2, Labor Day 1986","sub":"Read it in the Working Press collection","href":"../../working-press/"},{"k":"paper","label":"The Working Press, Vol. 1 No. 3, October 1986","sub":"Read it in the Working Press collection","href":"../../working-press/"}],"thumb":"../../working-press/thumb/p0015b.jpg","note":null},{"id":"ithaca-gun","date":"1986-10","sort":"1986-10-15","year":1986,"label":"October 1986","era":"founding","title":"Ithaca Gun and the bank","summary":"The Working Press follows the fate of the Ithaca Gun Company, its loans from Citizens Savings Bank and the city’s Economic Development Agency.","body":["How the story ended is not settled in the issues read so far."],"themes":["closings"],"orgs":["tclc"],"sources":[{"k":"paper","label":"The Working Press, Vol. 1 No. 3, October 1986","sub":"Read it in the Working Press collection","href":"../../working-press/"}],"thumb":"../../working-press/thumb/p0022b.jpg","note":"The final outcome of the Ithaca Gun sale is not resolved in the sources read so far."},{"id":"toy-drive","date":"1987-01","sort":"1987-01-15","year":1987,"label":"Winter 1986–87","era":"founding","title":"A holiday toy drive for strikers’ children","summary":"The coalition’s holiday campaign to give toys to the children of striking Cargill miners is \"a huge success.\"","body":["The same issue reported record union phone banking in the 1986 elections and complaints of anti-labor bias at the Ithaca Journal."],"themes":["strikes","solidarity"],"orgs":["tclc"],"sources":[{"k":"paper","label":"The Working Press, Vol. 2 No. 1, January 1987","sub":"Read it in the Working Press collection","href":"../../working-press/"}],"thumb":"../../working-press/thumb/p0026b.jpg","note":null},{"id":"cargill-decert","date":"1987-03-12","sort":"1987-03-12","year":1987,"label":"March 12, 1987","era":"founding","title":"\"Cargill Busts Union\"","summary":"In an NLRB decertification election the union at the Lansing mine is voted out, after nearly a year on strike.","body":["The Working Press called it \"a sad day for the entire Tompkins County community.\" The fight did not end there: in 1989 the county Board of Representatives argued over whether to buy road salt from Cargill at all."],"themes":["strikes"],"orgs":["private","tclc"],"sources":[{"k":"paper","label":"The Working Press, Vol. 2 No. 2, March 1987","sub":"Read it in the Working Press collection","href":"../../working-press/"},{"k":"paper","label":"The Working Press, Vol. 4 No. 3, June 1989","sub":"From the OCR transcription of the full run; page images not yet online","href":null}],"thumb":"../../working-press/thumb/p0030a.jpg","note":null},{"id":"csea-855-no-contract","date":"1987-05-05","sort":"1987-05-05","year":1987,"label":"May 1987","era":"founding","title":"County workers go without a contract","summary":"About 110 people turn out as the Tompkins County unit of CSEA Local 855 keeps working without a contract.","body":["CSEA argued for a fair wage comparable to neighboring counties. In the same issue Al Davidoff wrote about organizing clerical workers."],"themes":["contracts"],"orgs":["public"],"sources":[{"k":"paper","label":"The Working Press, Vol. 2 No. 3, May 1987","sub":"Read it in the Working Press collection","href":"../../working-press/"},{"k":"paper","label":"The Working Press, Vol. 2 No. 2, March 1987","sub":"Read it in the Working Press collection","href":"../../working-press/"}],"thumb":"../../working-press/thumb/p0037b.jpg","note":null},{"id":"ithaca-compact","date":"1987-08-05","sort":"1987-08-05","year":1987,"label":"August 1987","era":"founding","title":"The plant-closing fight ends in an \"Ithaca Compact\"","summary":"Instead of an ordinance, the mayor asks Common Council to fund a contract with the labor community for employment stabilization services.","body":["Jim Morrissette negotiated the compromise with Citizens Savings Bank and the mayor through 1987. The final version had the coalition employ a half-time staff member. Mayor Gutenberger’s memo thanked the business, labor and university members of his committee.","The Working Press reported in September that the coalition had \"salvaged a plant closing and layoff agreement for the City of Ithaca.\""],"themes":["closings","politics"],"orgs":["tclc","gov"],"sources":[{"k":"archive","label":"Jim Morrissette's proposal for an “Ithaca Compact”","sub":"Labor Coalition records · February 14, 1987 · Letter","href":"../tclc/items/tclc-0193/","id":"tclc-0193"},{"k":"archive","label":"Final proposal for the Ithaca Compact","sub":"Labor Coalition records · May 19, 1987 · Letter","href":"../tclc/items/tclc-0194/","id":"tclc-0194"},{"k":"archive","label":"Mayor John Gutenberger to Common Council: “Employment Legislation”","sub":"Labor Coalition records · August 5, 1987 · Memorandum","href":"../tclc/items/tclc-0195/","id":"tclc-0195"},{"k":"paper","label":"The Working Press, Vol. 2 No. 5, September 1987","sub":"From the OCR transcription of the full run; page images not yet online","href":null}],"thumb":"../tclc/media/thumb/b36-133.webp","note":null},{"id":"share-the-wealth-1987","date":"1987-10","sort":"1987-10-15","year":1987,"label":"October 1987","era":"founding","title":"Three days when Cornell construction stopped","summary":"During a UAW Local 2300 strike over poverty wages, about 900 building tradespeople stay off the job and $100 million of construction at Cornell goes quiet.","body":["The local’s 1987 negotiations covered more than 900 service and maintenance workers and aimed to \"eliminate poverty in our bargaining unit.\" The Working Press printed a full solidarity page of supporters.","The \"Share the Wealth\" fight carried into a new contract in 1988."],"themes":["strikes","contracts","solidarity"],"orgs":["uaw2300","trades"],"sources":[{"k":"paper","label":"The Working Press, Vol. 2 No. 6, November 1987","sub":"From the OCR transcription of the full run; page images not yet online","href":null},{"k":"paper","label":"The Working Press, Vol. 2 No. 5, September 1987","sub":"From the OCR transcription of the full run; page images not yet online","href":null},{"k":"paper","label":"The Working Press, Vol. 3 No. 3, Labor Day 1988","sub":"From the OCR transcription of the full run; page images not yet online","href":null}],"thumb":null,"note":null},{"id":"staff-hired","date":"1988","sort":"1988-06-30","year":1988,"label":"1988","era":"coalition","title":"The Coalition hires full-time staff","summary":"Coert Bonthius becomes the Coalition’s first full-time staff person. Among his duties is a health and safety program funded by New York State.","body":["The first contract with the New York State Department of Labor ran from July 1988 to June 1989, for up to $27,999.94. It targeted asbestos and the chemicals in custodial work, with UAW Local 2300 at Cornell and Teamsters Local 65 dairy workers.","The grants were renewed for years and paid for much of the Coalition’s staff."],"themes":["safety","founding"],"orgs":["tclc"],"sources":[{"k":"archive","label":"State health and safety training contract, July 1988 – June 1989","sub":"Labor Coalition records · July 1, 1988 – June 30, 1989 · Agreement","href":"../tclc/items/tclc-0232/","id":"tclc-0232"},{"k":"archive","label":"Correspondence with the Department of Labor on the 1988–89 contract budget","sub":"Labor Coalition records · July 26–28, 1988 · Letter","href":"../tclc/items/tclc-0234/","id":"tclc-0234"},{"k":"paper","label":"The Working Press, Vol. 3 No. 3, Labor Day 1988","sub":"From the OCR transcription of the full run; page images not yet online","href":null}],"thumb":"../tclc/media/thumb/b5-141.webp","note":null},{"id":"labor-day-1988","date":"1988-09-05","sort":"1988-09-05","year":1988,"label":"Labor Day 1988","era":"coalition","title":"\"Celebrate 100 Years of Labor in Ithaca\"","summary":"The 1988 picnic marks a century of organized labor in Ithaca, with hot air balloon rides and a history of Ithaca’s cigar makers’ strike.","body":["The same Labor Day issue announced that the state had awarded $28,000 to aid local workers and that UAW 2300’s \"Share the Wealth\" struggle had ended in a new contract."],"themes":["laborday","contracts"],"orgs":["tclc","uaw2300"],"sources":[{"k":"paper","label":"The Working Press, Vol. 3 No. 3, Labor Day 1988","sub":"From the OCR transcription of the full run; page images not yet online","href":null}],"thumb":null,"note":null},{"id":"ithaca-times","date":"1988-11","sort":"1988-11-15","year":1988,"label":"November 1988","era":"coalition","title":"Ithaca Times workers ask for mediation","summary":"Workers at Ithaca’s alternative weekly cite \"poverty wages\" and zero benefits and request mediation in their talks.","body":["The same issue carried a Labor Alert for the Ithaca Teachers Association and news of a UAW agreement at the Ithaca Housing Authority."],"themes":["contracts"],"orgs":["uaw2300"],"sources":[{"k":"paper","label":"The Working Press, Vol. 3 No. 4, November 1988","sub":"From the OCR transcription of the full run; page images not yet online","href":null}],"thumb":null,"note":null},{"id":"plant-closing-law-letters","date":"1989-03-13","sort":"1989-03-13","year":1989,"label":"March 1989","era":"coalition","title":"Telling employers about the new federal plant-closing law","summary":"After the 1988 federal WARN Act, the Coalition writes to 30 area businesses about advance notice and asks to meet.","body":["At least one, Triangle Steel, replied that with well under 100 employees it was not covered."],"themes":["closings"],"orgs":["tclc"],"sources":[{"k":"archive","label":"Letter to Ithaca-area businesses on the new federal plant closing law","sub":"Labor Coalition records · March 13, 1989 · Letter","href":"../tclc/items/tclc-0134/","id":"tclc-0134"},{"k":"archive","label":"Cover letter on the mailing to 30 businesses","sub":"Labor Coalition records · March 13, 1989 · Letter","href":"../tclc/items/tclc-0135/","id":"tclc-0135"},{"k":"archive","label":"Triangle Steel's reply","sub":"Labor Coalition records · March 14, 1989 · Letter","href":"../tclc/items/tclc-0136/","id":"tclc-0136"},{"k":"archive","label":"“Highlights of the 1988 Plant Closing Law”","sub":"Labor Coalition records · [1989] · Fact sheet","href":"../tclc/items/tclc-0133/","id":"tclc-0133"}],"thumb":"../tclc/media/thumb/b36-020.webp","note":null},{"id":"pall-trinity","date":"1989-04","sort":"1989-04-15","year":1989,"label":"April 1989","era":"coalition","title":"\"Unity Ends Concessions\" at Pall Trinity","summary":"The Cortland UAW wins a victory at Pall Trinity, backed by speakers from eight local unions at a March 14 rally.","body":["Howard Botwinick of UUP wrote the story. A month later the paper reported Powerex workers striking to save jobs and graduate teaching assistants rallying at Cornell’s Day Hall."],"themes":["contracts","solidarity"],"orgs":["private","tclc"],"sources":[{"k":"paper","label":"The Working Press, Vol. 4 No. 2, April 1989","sub":"From the OCR transcription of the full run; page images not yet online","href":null}],"thumb":null,"note":null},{"id":"gao-rally","date":"1989-04-21","sort":"1989-04-21","year":1989,"label":"April 21, 1989","era":"coalition","title":"Cornell teaching assistants organize","summary":"More than 400 graduate students rally in front of Day Hall with the Graduate Advocacy Organization.","body":["The GAO planned a formal membership drive that fall. In November 1991 the Working Press ran \"Graduate Students Need a Union Too.\""],"themes":["organizing"],"orgs":["students","uaw2300"],"sources":[{"k":"paper","label":"The Working Press, Vol. 4 No. 3, June 1989","sub":"From the OCR transcription of the full run; page images not yet online","href":null},{"k":"paper","label":"The Working Press, Vol. 6 No. 6, November 1991","sub":"From the OCR transcription of the full run; page images not yet online","href":null}],"thumb":null,"note":null},{"id":"smith-corona-layoffs","date":"1990-05","sort":"1990-05-15","year":1990,"label":"1990","era":"coalition","title":"\"Smith Corona Lays Off 350 Without Warning\"","summary":"The Coalition investigates layoffs at Smith Corona’s Cortland typewriter plant and whether the company dodged the 60-day notice required by WARN.","body":["Area unions called for an investigation, surveyed laid-off workers and wrote to county legislators and Assembly members. Carol Kates of UAW 2300 did much of the research. The Sugar Law Center in Detroit backed the case.","A May 8, 1991 press conference was titled \"Smith Corona Runaway, But the Law Can’t Touch Them.\" Bonthius closed out the case in June 1991 as he prepared to leave the Coalition. Smith Corona later moved typewriter production to Mexico, and the NAFTA fight of 1993 kept returning to its example."],"themes":["closings","politics"],"orgs":["tclc"],"sources":[{"k":"archive","label":"The Working Press, Volume 5, Number 2, May 1990: Smith Corona layoffs","sub":"Labor Coalition records · May 1990 · Newsletter","href":"../tclc/items/tclc-0227/","id":"tclc-0227"},{"k":"archive","label":"Press statement: “Unions Call for Investigation of Smith Corona Lay Offs”","sub":"Labor Coalition records · [Early 1990] · Press release","href":"../tclc/items/tclc-0200/","id":"tclc-0200"},{"k":"archive","label":"“Profile on Smith Corona Layoffs: Possible Violation of the Federal Plant Closing Law (WARN)”","sub":"Labor Coalition records · [1990] · Report","href":"../tclc/items/tclc-0216/","id":"tclc-0216"},{"k":"archive","label":"Coert Bonthius to Cortland County Legislature chair Richard Tupper on Smith Corona","sub":"Labor Coalition records · April 24, 1990 · Letter","href":"../tclc/items/tclc-0217/","id":"tclc-0217"},{"k":"archive","label":"Sugar Law Center news release opposing the Smith Corona layoffs","sub":"Labor Coalition records · February 1, 1991 · Press release","href":"../tclc/items/tclc-0207/","id":"tclc-0207"},{"k":"archive","label":"Press conference agenda: “Smith Corona Runaway, But the Law Can't Touch Them”","sub":"Labor Coalition records · May 8, 1991 · Agenda","href":"../tclc/items/tclc-0224/","id":"tclc-0224"},{"k":"archive","label":"Coert Bonthius's closing letters on the Smith Corona case, June 7, 1991","sub":"Labor Coalition records · June 7, 1991 · Letter","href":"../tclc/items/tclc-0225/","id":"tclc-0225"},{"k":"archive","label":"Resolution of the Board of Supervisors of the City of Cortland on Smith Corona","sub":"Labor Coalition records · [1992] · Agreement","href":"../tclc/items/tclc-0201/","id":"tclc-0201"},{"k":"archive","label":"Resolution of the Cortland County Legislators on Smith Corona","sub":"Labor Coalition records · [1992] · Agreement","href":"../tclc/items/tclc-0226/","id":"tclc-0226"}],"thumb":"../tclc/media/thumb/b36-278.webp","note":null},{"id":"safety-program","date":"1990-07-20","sort":"1990-07-20","year":1990,"label":"1990–1992","era":"coalition","title":"A health and safety program for the whole region","summary":"Carl Feuer and Robin Whittlesey run workshops, back injury clinics and a newsletter for office workers under the state grants.","body":["The 1990–91 report lists clinics with CSEA Local 605, school district employees, APWU 1151 and UAW 2300, and work with union safety committees at Monarch Machine Tool, Pall Trinity and Brewer-Titchener. The newsletters ran stories such as \"Formaldehyde Hazard at Pall Trinity?\" and \"Air Quality Improvements Won at Cornell.\"","The Coalition held its first Workers Memorial Day events after Charlie Streeter was killed on the job."],"themes":["safety"],"orgs":["tclc","public","private"],"sources":[{"k":"archive","label":"Summary of health and safety training workshops, June 1990","sub":"Labor Coalition records · July 20, 1990 · Report","href":"../tclc/items/tclc-0246/","id":"tclc-0246"},{"k":"archive","label":"Health and Safety Program annual report, 1990–1991","sub":"Labor Coalition records · [1991] · Report","href":"../tclc/items/tclc-0255/","id":"tclc-0255"},{"k":"archive","label":"“Formaldehyde Hazard at Pall Trinity?”","sub":"Labor Coalition records · [c. 1990–1991] · Newsletter","href":"../tclc/items/tclc-0247/","id":"tclc-0247"},{"k":"archive","label":"“The Sweet Smell of Success: Air Quality Improvements Won at Cornell”","sub":"Labor Coalition records · [c. 1990–1991] · Newsletter","href":"../tclc/items/tclc-0248/","id":"tclc-0248"},{"k":"archive","label":"FYI: A Health and Safety Newsletter for Office Workers, September 1991","sub":"Labor Coalition records · September 1991 · Newsletter","href":"../tclc/items/tclc-0258/","id":"tclc-0258"}],"thumb":"../tclc/media/thumb/b5-140.webp","note":null},{"id":"pico-trial","date":"1991","sort":"1991-06-30","year":1991,"label":"1991","era":"coalition","title":"The Pico trial in Binghamton","summary":"Korean women workers sue Pico Products in a Binghamton federal court after the company closes their plant in South Korea, and the Working Press covers it.","body":["A Cornell graduate student wrote that an American spectator took one of the women’s hands and told her she would go down in labor history."],"themes":["solidarity","closings"],"orgs":["tclc","students"],"sources":[{"k":"paper","label":"The Working Press, Vol. 6 No. 6, November 1991","sub":"From the OCR transcription of the full run; page images not yet online","href":null},{"k":"archive","label":"“Union Tools” and “Historic Pico Trial in Binghamton Court”","sub":"Labor Coalition records · [1991] · Newsletter","href":"../tclc/items/tclc-0253/","id":"tclc-0253"}],"thumb":"../tclc/media/thumb/b5-155.webp","note":null},{"id":"labor-day-1991","date":"1991-09","sort":"1991-09-15","year":1991,"label":"Labor Day 1991","era":"coalition","title":"The eighth annual picnic, and a trip to Solidarity Day","summary":"Volunteers run the 8th annual Labor Day picnic and the Coalition goes to Solidarity Day in Washington.","body":["The paper thanked the volunteers without whom \"the Labor Coalition would not be able to function.\""],"themes":["laborday","solidarity"],"orgs":["tclc"],"sources":[{"k":"paper","label":"The Working Press, Vol. 6 No. 6, November 1991","sub":"From the OCR transcription of the full run; page images not yet online","href":null}],"thumb":null,"note":null},{"id":"four-counties","date":"1992-02","sort":"1992-02-15","year":1992,"label":"1992","era":"coalition","title":"Four counties: Tompkins, Cortland, Schuyler and Seneca","summary":"The Working Press masthead adds Schuyler and Seneca counties as their unions join.","body":["A public sector solidarity conference was called for March 1992. That spring the Coalition also reported on Schuyler County layoffs."],"themes":["founding"],"orgs":["tclc","public"],"sources":[{"k":"paper","label":"The Working Press, Vol. 7 No. 1, February 1992","sub":"From the OCR transcription of the full run; page images not yet online","href":null},{"k":"paper","label":"The Working Press, Vol. 7 No. 2, spring 1992","sub":"From the OCR transcription of the full run; page images not yet online","href":null}],"thumb":null,"note":null},{"id":"workers-memorial-1992","date":"1992-04-25","sort":"1992-04-25","year":1992,"label":"April 25–28, 1992","era":"coalition","title":"Workers Memorial Day, for Hamlet","summary":"Seventy-five people attend a memorial and OSHA reform rally in Ithaca dedicated to the 25 workers killed in the Hamlet, North Carolina poultry plant fire.","body":["On April 28 the city’s fire horns and the Cornell chimes signaled a moment of silence. The Coalition also met with the district attorneys of Tompkins, Cortland and Schuyler counties about prosecuting workplace safety crimes."],"themes":["safety"],"orgs":["tclc","gov"],"sources":[{"k":"archive","label":"Workers Memorial Day events report, April 1992","sub":"Labor Coalition records · April 1992 · Report","href":"../tclc/items/tclc-0262/","id":"tclc-0262"},{"k":"paper","label":"The Working Press, Vol. 7 No. 2, spring 1992","sub":"From the OCR transcription of the full run; page images not yet online","href":null}],"thumb":"../tclc/media/thumb/b5-179.webp","note":null},{"id":"charter-request","date":"1992-10-05","sort":"1992-10-05","year":1992,"label":"October 5, 1992","era":"coalition","title":"The Coalition asks the AFL-CIO for a charter","summary":"Coordinator Brett Nair writes to AFL-CIO Region VII director Mary Fears Crayton asking to charter the Coalition as a labor council.","body":["The local paper reported the vote: of about 25 member unions voting on September 30, the only dissent came from an independent BOCES employee. Nair called the mood \"cautious optimism.\" Howard Botwinick of UUP called it \"an issue of solidarity.\""],"themes":["founding"],"orgs":["tclc"],"sources":[{"k":"archive","label":"Brett Nair to Mary Fears Crayton, requesting an AFL-CIO labor council charter","sub":"Labor Coalition records · October 5, 1992 · Letter","href":"../tclc/items/tclc-0018/","id":"tclc-0018"}],"thumb":"../tclc/media/thumb/b1-062.webp","note":null},{"id":"name-contest","date":"1992-11","sort":"1992-11-15","year":1992,"label":"November 1992","era":"coalition","title":"\"Name the Labor Coalition!\"","summary":"The Working Press offers $50 for a new name. Readers send in Finger Lakes Labor Coalition, Labor C.O.R.E., 4RCLC and \"The Ithaca Labor Council.\"","body":["One reader wrote that everyone would call it the Ithaca Labor Council anyway. The name that stuck, after affiliation, was the Mid-State (later Midstate) Central Labor Council."],"themes":["founding","press"],"orgs":["tclc"],"sources":[{"k":"archive","label":"“Name the Labor Coalition!” contest notice, with an entry from Frank Annunziata","sub":"Labor Coalition records · December [1992] · Letter","href":"../tclc/items/tclc-0011/","id":"tclc-0011"}],"thumb":"../tclc/media/thumb/b1-045.webp","note":null},{"id":"affiliation-route","date":"1993-03-19","sort":"1993-03-19","year":1993,"label":"March 1993","era":"coalition","title":"Two routes into the AFL-CIO","summary":"A memo to the Steering Committee weighs building a parallel \"labor council\" inside the Coalition against fighting the AFL-CIO over the first draft constitution.","body":["The Coalition wanted to keep independents, individual members and community groups, which AFL-CIO rules did not allow in a central labor council. The compromise kept the Coalition and the council side by side."],"themes":["founding"],"orgs":["tclc"],"sources":[{"k":"archive","label":"Memo to the Steering Committee: AFL-CIO affiliation process and bylaws","sub":"Labor Coalition records · March 19, 1993 · Memorandum","href":"../tclc/items/tclc-0016/","id":"tclc-0016"},{"k":"archive","label":"Rules Governing AFL-CIO Local Central Bodies (pamphlet)","sub":"Labor Coalition records · Issued February 26, 1973 · Pamphlet","href":"../tclc/items/tclc-0001/","id":"tclc-0001"},{"k":"archive","label":"“Suggestion Constitution for the Tompkins County Central Labor Council”","sub":"Labor Coalition records · Undated [1980s] · Constitution or rules","href":"../tclc/items/tclc-0164/","id":"tclc-0164"}],"thumb":"../tclc/media/thumb/b1-052.webp","note":null},{"id":"oates-fired","date":"1993-08-04","sort":"1993-08-04","year":1993,"label":"August 4, 1993","era":"coalition","title":"Ithaca’s postmaster fires the APWU local president","summary":"Mike Oates, president of APWU Local 1151 and a window clerk at the Tioga Street station, is fired. The Coalition calls it an attack on the union.","body":["A year later a co-worker wrote \"The Year Our Union President Was Fired\" for the Working Press, describing Oates’s fight to come back."],"themes":["rights"],"orgs":["public","tclc"],"sources":[{"k":"paper","label":"The Working Press, Labor Day 1993 solidarity pages","sub":"From the OCR transcription of the full run; page images not yet online","href":null},{"k":"paper","label":"The Working Press, Vol. 9 No. 4, August 1994 (Solidarity Issue)","sub":"From the OCR transcription of the full run; page images not yet online","href":null}],"thumb":null,"note":null},{"id":"nafta-fight","date":"1993-08-17","sort":"1993-08-17","year":1993,"label":"August–November 1993","era":"coalition","title":"Fighting NAFTA","summary":"The Coalition joins labor, environmental and religious groups at a Cortland press conference against NAFTA’s side agreements, then runs phone banks before the vote.","body":["The groups said the side agreements had no timelines or enforcement and would speed plant closings like Smith Corona’s. A 1996 Working Press headline was \"We Told You So! NAFTA Fails to Deliver Jobs.\""],"themes":["politics","closings"],"orgs":["tclc"],"sources":[{"k":"archive","label":"Press release: citizen groups respond to the NAFTA side agreements","sub":"Labor Coalition records · August 17, [1993] · Press release","href":"../tclc/items/tclc-0265/","id":"tclc-0265"},{"k":"archive","label":"NAFTA side agreements seminar in Syracuse, September 29, 1993","sub":"Labor Coalition records · September 29, 1993 · Press release","href":"../tclc/items/tclc-0267/","id":"tclc-0267"},{"k":"archive","label":"NAFTA alert to member unions, with legislators list and phone-bank script","sub":"Labor Coalition records · [October–November 1993] · Letter","href":"../tclc/items/tclc-0264/","id":"tclc-0264"},{"k":"paper","label":"The Working Press, Vol. 12 No. 1, July 1996","sub":"From the OCR transcription of the full run; page images not yet online","href":null}],"thumb":"../tclc/media/thumb/b5-191.webp","note":null},{"id":"constitution-adopted","date":"1993-10-06","sort":"1993-10-06","year":1993,"label":"October 6, 1993","era":"coalition","title":"Forty people from 21 unions adopt a new constitution","summary":"At the TC3 Forum Auditorium, members of the Tompkins/Cortland Labor Coalition vote to adopt the constitution of the Mid-State Central Labor Council, AFL-CIO.","body":["Co-chairs Lore Oswald (Schuyler), Al Davidoff (Tompkins) and Willis Streeter (Cortland) had sent it out as a compromise that let the Coalition keep working \"in much the same manner as we have been.\" Coert Bonthius exchanged drafts with the AFL-CIO’s Leonard Lewis through September."],"themes":["founding"],"orgs":["tclc"],"sources":[{"k":"archive","label":"Coert Bonthius to Mary Crayton: the Coalition adopts its new constitution","sub":"Labor Coalition records · March 22, 1994 · Letter","href":"../tclc/items/tclc-0006/","id":"tclc-0006"},{"k":"archive","label":"Co-chairs to member unions: the proposed AFL-CIO constitution","sub":"Labor Coalition records · September 23, 1993 · Letter","href":"../tclc/items/tclc-0014/","id":"tclc-0014"},{"k":"archive","label":"Coert Bonthius to Leonard Lewis, on the revised constitution","sub":"Labor Coalition records · September 15, 1993 · Letter","href":"../tclc/items/tclc-0015/","id":"tclc-0015"},{"k":"archive","label":"Coert Bonthius to Leonard Lewis, sending the final draft constitution","sub":"Labor Coalition records · September 28, 1993 · Letter","href":"../tclc/items/tclc-0013/","id":"tclc-0013"}],"thumb":"../tclc/media/thumb/b1-020.webp","note":null},{"id":"borg-warner","date":"1993-11","sort":"1993-11-15","year":1993,"label":"Fall 1993","era":"coalition","title":"Borg-Warner workers strike for a week","summary":"Workers at Borg-Warner strike for a week. Coca-Cola workers in Elmira, Auburn and Binghamton push back against benefit cuts with the Teamsters.","body":["The November issue also announced a contract campaign training run with Cornell’s ILR School and steering committee elections for January 1994."],"themes":["strikes","contracts"],"orgs":["private","tclc"],"sources":[{"k":"paper","label":"The Working Press, Vol. 8 No. 4, November 1993","sub":"From the OCR transcription of the full run; page images not yet online","href":null}],"thumb":null,"note":null},{"id":"state-federation","date":"1994-01-31","sort":"1994-01-31","year":1994,"label":"January 31, 1994","era":"council","title":"Welcome to the New York State AFL-CIO","summary":"State federation secretary-treasurer Paul Cole welcomes the Mid-State Central Labor Council.","body":["Bonthius had written in December, \"At long last we are completing the affiliation process.\""],"themes":["founding"],"orgs":["tclc"],"sources":[{"k":"archive","label":"Paul F. Cole welcomes the Mid-State Central Labor Council to the New York State AFL-CIO","sub":"Labor Coalition records · January 31, 1994 · Letter","href":"../tclc/items/tclc-0009/","id":"tclc-0009"},{"k":"archive","label":"Coert Bonthius to Paul Cole on completing affiliation","sub":"Labor Coalition records · December 16, 1993 · Letter","href":"../tclc/items/tclc-0010/","id":"tclc-0010"}],"thumb":"../tclc/media/thumb/b1-040.webp","note":null},{"id":"cristianos","date":"1994-04","sort":"1994-04-15","year":1994,"label":"Spring 1994","era":"council","title":"A march on Cristiano’s Pizza","summary":"After a fired worker comes to the Coalition for his last week’s pay, students and unionists march on an Ithaca pizzeria accused of not paying its workers.","body":["The Working Press headline was \"Pizza and Justice: Ithaca Pizzeria Stiffs Staff.\" The restaurant closed as the marchers approached. The Workers’ Center later counted this among the campaigns it inherited from the Coalition."],"themes":["rights"],"orgs":["tclc","students"],"sources":[{"k":"paper","label":"The Working Press, Vol. 9 No. 2, May 1994","sub":"From the OCR transcription of the full run; page images not yet online","href":null},{"k":"doc","label":"Carl Feuer and Pete Meyers, “Solidarity in One Community: How Worker Centers Can Work with Organized Labor,” Tompkins County Workers' Center case study","sub":null,"href":null}],"thumb":null,"note":null},{"id":"charter-approved","date":"1994-05-04","sort":"1994-05-04","year":1994,"label":"May 4, 1994","era":"council","title":"Lane Kirkland approves the Mid-State Central Labor Council","summary":"AFL-CIO President Lane Kirkland writes to council president Al Davidoff approving the charter, with jurisdiction over Cortland, Tompkins and Schuyler counties.","body":["The charter listed Davidoff (UAW 2300) as president, Lore Oswald (CSEA 849) as vice president, and Willis Streeter (CSEA 605) as secretary-treasurer. AFL-CIO staff had first flagged that Cortland County was on record as part of the Greater Syracuse council.","The Coalition did not dissolve. It kept its own name, newspaper and programs alongside the council. Its successor, the Midstate Central Labor Council, still exists."],"themes":["founding"],"orgs":["tclc"],"sources":[{"k":"archive","label":"Lane Kirkland to Al Davidoff, approving the Mid-State Central Labor Council charter","sub":"Labor Coalition records · May 4, 1994 · Letter","href":"../tclc/items/tclc-0002/","id":"tclc-0002"},{"k":"archive","label":"Ed Collins to Mary Crayton: review of the Mid-State charter application and constitution","sub":"Labor Coalition records · February 3, 1994 · Memorandum","href":"../tclc/items/tclc-0007/","id":"tclc-0007"},{"k":"archive","label":"Mary Fears Crayton to Coert Bonthius, enclosing the AFL-CIO charter application","sub":"Labor Coalition records · January 14, 1994 · Letter","href":"../tclc/items/tclc-0004/","id":"tclc-0004"}],"thumb":"../tclc/media/thumb/b1-008.webp","note":null},{"id":"walmart-resolution-1994","date":"1994-05-10","sort":"1994-05-10","year":1994,"label":"May 10, 1994","era":"council","title":"The Coalition weighs in on an Ithaca Wal-Mart","summary":"The Steering Committee unanimously sets \"minimum standards\" for a Wal-Mart proposed for Elmira Road.","body":["The resolution cited Wal-Mart’s anti-union record and the store’s environmental and social effects. The store opened in January 2005, and a living wage campaign was waiting for it."],"themes":["politics","wages"],"orgs":["tclc"],"sources":[{"k":"paper","label":"The Working Press, Vol. 9 No. 2, May 1994","sub":"From the OCR transcription of the full run; page images not yet online","href":null}],"thumb":null,"note":null},{"id":"cortland-office","date":"1994-05","sort":"1994-05-15","year":1994,"label":"May 1994","era":"council","title":"A Labor Coalition office in Cortland","summary":"Staff begin working out of CSEA Local 605’s office in Brockway Hall at SUNY Cortland at least one day a week.","body":["Most of the Coalition’s activity had been in Ithaca. The Cortland office was a first step toward the Workers Rights Board two years later."],"themes":["founding","organizing"],"orgs":["tclc","public"],"sources":[{"k":"paper","label":"The Working Press, Vol. 9 No. 2, May 1994","sub":"From the OCR transcription of the full run; page images not yet online","href":null}],"thumb":null,"note":null},{"id":"oasis-contract","date":"1994","sort":"1994-06-30","year":1994,"label":"1994","era":"council","title":"Oasis Natural Grocery workers ratify a first contract","summary":"Fourteen workers at Oasis ratify their first contract, two and a half years after organizing with UAW Local 2300 in 1991.","body":["The local had asked shoppers to wear \"I support the Oasis workers\" buttons."],"themes":["organizing","contracts"],"orgs":["uaw2300"],"sources":[{"k":"paper","label":"The Working Press, Vol. 9 No. 4, August 1994 (Solidarity Issue)","sub":"From the OCR transcription of the full run; page images not yet online","href":null},{"k":"paper","label":"The Working Press, Vol. 7 No. 2, spring 1992","sub":"From the OCR transcription of the full run; page images not yet online","href":null}],"thumb":null,"note":null},{"id":"single-payer","date":"1994-07","sort":"1994-07-15","year":1994,"label":"July 1994","era":"council","title":"Members endorse single-payer health care","summary":"A special issue on the health care crisis reports that the general membership endorsed a single-payer system.","body":["Theresa Alt, Howard Botwinick and Coert Bonthius wrote the case for single payer over the Clinton plan."],"themes":["politics"],"orgs":["tclc"],"sources":[{"k":"paper","label":"The Working Press, Vol. 9 No. 3, July 1994","sub":"From the OCR transcription of the full run; page images not yet online","href":null}],"thumb":null,"note":null},{"id":"catherwood","date":"1994-07","sort":"1994-07-15","year":1994,"label":"Summer 1994","era":"council","title":"Local union labor will build Catherwood Library","summary":"After lobbying of Governor Cuomo, the state construction fund requires local union labor for the remodel of Cornell’s ILR library.","body":["Tom Joyce of Painters 178 wrote that Cornell mattered as much to the unionized building trades as to the county economy."],"themes":["contracts","politics"],"orgs":["trades","students"],"sources":[{"k":"paper","label":"The Working Press, Vol. 9 No. 3, July 1994","sub":"From the OCR transcription of the full run; page images not yet online","href":null}],"thumb":null,"note":null},{"id":"randolph-exhibit","date":"1994-08","sort":"1994-08-15","year":1994,"label":"August 1994","era":"council","title":"An A. Philip Randolph exhibit opens","summary":"The Coalition brings an exhibit on the Sleeping Car Porters’ founder to Ithaca, linking racial and economic justice.","body":["The Solidarity Issue congratulated the paper on nine years and the Coalition on \"a Decade of Community/Labor Solidarity.\""],"themes":["solidarity"],"orgs":["tclc"],"sources":[{"k":"paper","label":"The Working Press, Vol. 8 No. 4, November 1993","sub":"From the OCR transcription of the full run; page images not yet online","href":null},{"k":"paper","label":"The Working Press, Vol. 9 No. 4, August 1994 (Solidarity Issue)","sub":"From the OCR transcription of the full run; page images not yet online","href":null}],"thumb":null,"note":null},{"id":"holiday-inn-1995","date":"1994-12-31","sort":"1994-12-31","year":1994,"label":"December 31, 1994","era":"council","title":"Holiday Inn workers win gains","summary":"UAW Local 2300’s bargaining team at the Ithaca Holiday Inn settles 23 hours before the old contract expires.","body":["The same January 1995 issue introduced Chuck Wynns as the Coalition’s new coordinator."],"themes":["contracts"],"orgs":["uaw2300","tclc"],"sources":[{"k":"paper","label":"The Working Press, January 1995","sub":"From the OCR transcription of the full run; page images not yet online","href":null}],"thumb":null,"note":null},{"id":"may-day-1995","date":"1995-05-01","sort":"1995-05-01","year":1995,"label":"May 1, 1995","era":"council","title":"600 to 700 tradespeople march on City Hall","summary":"Building trades workers and their children march from Washington Park to protest the city’s denial of building permits to Cornell.","body":["The Working Press called it the largest local labor demonstration in anyone’s memory. Mayor Ben Nichols came out to talk. The Coalition’s own resolution on the city-Cornell dispute caused an internal fight, and a staff memo that April listed the \"casualties\" of the conflict with the Building Trades."],"themes":["politics","founding"],"orgs":["trades","tclc","gov"],"sources":[{"k":"paper","label":"The Working Press, Vol. 11 No. 2, June 1995","sub":"From the OCR transcription of the full run; page images not yet online","href":null},{"k":"archive","label":"Memo: “Casualties” of the conflict between the Building Trades and the Labor Coalition","sub":"Labor Coalition records · April 28, 1995 · Memorandum","href":"../tclc/items/tclc-0105/","id":"tclc-0105"}],"thumb":"../tclc/media/thumb/b1-338.webp","note":null},{"id":"red-cross-shelter","date":"1995-06","sort":"1995-06-15","year":1995,"label":"1995","era":"council","title":"Shelter workers go union","summary":"Staff at the Tompkins County Red Cross shelter organize with UAW Local 2300.","body":["A 1996 article followed up on the troubles at the Red Cross after the vote."],"themes":["organizing"],"orgs":["uaw2300"],"sources":[{"k":"paper","label":"The Working Press, Vol. 11 No. 2, June 1995","sub":"From the OCR transcription of the full run; page images not yet online","href":null},{"k":"paper","label":"The Working Press, Vol. 12 No. 1, July 1996","sub":"From the OCR transcription of the full run; page images not yet online","href":null}],"thumb":null,"note":null},{"id":"cortland-wrb","date":"1996","sort":"1996-06-30","year":1996,"label":"1996","era":"council","title":"The Cortland Workers Rights Board","summary":"The Coalition opens a Workers Rights Board on Court Street in Cortland to take complaints from workers without unions.","body":["It was modeled on Workers Rights Boards started by Jobs with Justice. Volunteers, mostly UAW leaders, handled about 100 complaints a year with help from Ithaca-based staff. It became the model for the Workers’ Center hotline in 2003."],"themes":["rights","organizing"],"orgs":["tclc","private"],"sources":[{"k":"doc","label":"Carl Feuer and Pete Meyers, “Solidarity in One Community: How Worker Centers Can Work with Organized Labor,” Tompkins County Workers' Center case study","sub":null,"href":null},{"k":"doc","label":"Carl Feuer and Pete Meyers, “How Can Worker Centers Work with Traditional Unions?” AFL-CIO blog, 2013","sub":null,"href":null},{"k":"archive","label":"“A Comprehensive Organizing Program for South-Central New York”: grant proposal","sub":"Labor Coalition records · May 1996 · Proposal","href":"../tclc/items/tclc-0102/","id":"tclc-0102"}],"thumb":"../tclc/media/thumb/b1-330.webp","note":"The case study gives 1996. The 2013 AFL-CIO blog post gives 1997."},{"id":"justice-for-all","date":"1996","sort":"1996-06-30","year":1996,"label":"1996","era":"council","title":"Justice for All organizes in the community","summary":"A new community group collects 1,000 signatures for a \"Fair Share\" tax pledge and co-hosts a speak-out on the minimum wage with the labor council.","body":["Justice for All later folded into the Living Wage Coalition."],"themes":["wages","politics"],"orgs":["tcwc","tclc"],"sources":[{"k":"paper","label":"The Working Press, Vol. 12 No. 2, Labor Day 1996","sub":"From the OCR transcription of the full run; page images not yet online","href":null}],"thumb":null,"note":null},{"id":"maidenform","date":"1996-07","sort":"1996-07-15","year":1996,"label":"July 1996","era":"council","title":"UNITE wins a contract at Maidenform","summary":"Carl Feuer and Mandy Ellis report a contract win for UNITE at Maidenform, and SEIU 200A settles at Corning Hospital.","body":["The same issue covered the founding convention of the Labor Party, which area activists including Howard Botwinick, Chuck Wynns and Mark Keith attended."],"themes":["contracts"],"orgs":["private","tclc"],"sources":[{"k":"paper","label":"The Working Press, Vol. 12 No. 1, July 1996","sub":"From the OCR transcription of the full run; page images not yet online","href":null}],"thumb":null,"note":null},{"id":"goat-1996","date":"1996-09-02","sort":"1996-09-02","year":1996,"label":"Labor Day 1996","era":"council","title":"Goat of Labor: Cortland Transit’s owner","summary":"The Goat of Labor goes to Tom Freeman of Cortland Transit, who had met Teamsters Local 317 for only eleven bargaining sessions.","body":["The union represented about 20 drivers, aides and maintenance workers. The picnic that year ran from noon to 4 at the large pavilion in Stewart Park."],"themes":["laborday","contracts"],"orgs":["private","tclc"],"sources":[{"k":"paper","label":"The Working Press, Vol. 12 No. 2, Labor Day 1996","sub":"From the OCR transcription of the full run; page images not yet online","href":null}],"thumb":null,"note":null},{"id":"union-cities","date":"1997-01-03","sort":"1997-01-03","year":1997,"label":"1997","era":"council","title":"Union Cities and a network of small councils","summary":"AFL-CIO President John Sweeney introduces Union Cities. The Coalition proposes that small councils in Steuben, Chemung and Midstate share an organizer.","body":["In February Kate Bronfenbrenner spoke at TC3 on \"What the Labor Movement Needs to Do to Survive and Grow.\" In March Al Davidoff left to become the AFL-CIO’s director for New York State. A June 1998 Working Press laid out the program step by step."],"themes":["organizing","founding"],"orgs":["tclc"],"sources":[{"k":"archive","label":"John J. Sweeney to Al Davidoff on Union Cities, with “Union Cities: Equal Strong Communities”","sub":"Labor Coalition records · January 3, 1997 · Letter","href":"../tclc/items/tclc-0091/","id":"tclc-0091"},{"k":"archive","label":"“'Union Cities' Network Proposal for Small Central Labor Councils”","sub":"Labor Coalition records · [1997] · Proposal","href":"../tclc/items/tclc-0122/","id":"tclc-0122"},{"k":"archive","label":"Press release: Kate Bronfenbrenner to speak on “What the Labor Movement Needs to Do to Survive and Grow”","sub":"Labor Coalition records · February 7, 1997 · Press release","href":"../tclc/items/tclc-0094/","id":"tclc-0094"},{"k":"archive","label":"Press release: “Union Leader Takes New Position” (Al Davidoff)","sub":"Labor Coalition records · March 25, 1997 · Press release","href":"../tclc/items/tclc-0087/","id":"tclc-0087"},{"k":"archive","label":"The Working Press, Volume 1, Issue 6, June 1998: “Building the Road to Union Cities”","sub":"Labor Coalition records · June 1998 · Newsletter","href":"../tclc/items/tclc-0076/","id":"tclc-0076"}],"thumb":"../tclc/media/thumb/b1-306.webp","note":null},{"id":"living-wage-coalition","date":"1997","sort":"1997-06-30","year":1997,"label":"1997–1999","era":"council","title":"A Living Wage Coalition and the \"Fund for Fairness\"","summary":"A Tompkins County Living Wage Coalition forms within Justice for All and wins county money to raise human service workers on county contracts to a living wage.","body":["The coalition included the Labor Coalition, UAW Local 2300, the Multicultural Resource Center, the Latino Civic Association, COLA and DSA. Cornell students in COLA interviewed low-paid human service workers for a report called \"Voices of the Workers.\"","The raises reached 31 workers at county-funded agencies, by an average of 13 percent in 1999. The coalition called it only the second measure of its kind in the country. The Workers’ Center counts this as the first step in its own history."],"themes":["wages","politics"],"orgs":["tcwc","gov","tclc","students"],"sources":[{"k":"doc","label":"Tompkins County Workers' Center, organizational history chronology (unpublished draft); dated public events only","sub":null,"href":null},{"k":"doc","label":"Carl Feuer and Pete Meyers, “Solidarity in One Community: How Worker Centers Can Work with Organized Labor,” Tompkins County Workers' Center case study","sub":null,"href":null}],"thumb":null,"note":"The chronology dates the county program to 1997, with $37,000 in its first year. Carl Feuer’s account of the \"Fund for Fairness\" campaign dates it to 1998, with $56,000 over two years starting in 1999. They appear to describe the same program."},{"id":"holiday-inn-hearing","date":"1997-11-19","sort":"1997-11-19","year":1997,"label":"November 19, 1997","era":"council","title":"A public hearing on Holiday Inn wages","summary":"Six workers testify before a community panel that finds Holiday Inn wages \"insufficient to sustain a decent standard of living.\"","body":["The panel was made up of a county legislator, a Cornell labor professor and a human service leader. It urged Hart Hotels to pay a livable wage. Public hearings like this one came from the Workers Rights Board movement."],"themes":["wages","contracts"],"orgs":["uaw2300","tclc"],"sources":[{"k":"doc","label":"Tompkins County Workers' Center, organizational history chronology (unpublished draft); dated public events only","sub":null,"href":null}],"thumb":null,"note":null},{"id":"cmc-nurses-1998","date":"1998-10","sort":"1998-10-15","year":1998,"label":"October 1998","era":"council","title":"\"Nurses Need Your Help!\"","summary":"A Labor Alert asks for support for registered nurses at Cayuga Medical Center organizing with CSEA over understaffing and mandatory long shifts.","body":["That fall the council also won a $21,000 share of a federal OSHA training grant, thanked by Teamsters Local 317 for help at Central State Beef and Veal, and covered Newfield teachers on the picket line."],"themes":["organizing","safety"],"orgs":["tclc","public"],"sources":[{"k":"archive","label":"LABOR ALERT: “Nurses Need Your Help!” (Cayuga Medical Center)","sub":"Labor Coalition records · [October 1998] · Flyer","href":"../tclc/items/tclc-0073/","id":"tclc-0073"},{"k":"archive","label":"Press release: “Local Labor Council Wins OSHA Grant”","sub":"Labor Coalition records · October 20, 1998 · Press release","href":"../tclc/items/tclc-0072/","id":"tclc-0072"},{"k":"archive","label":"Teamsters Local 317 thanks the Midstate Central Labor Council","sub":"Labor Coalition records · October 13, 1998 · Letter","href":"../tclc/items/tclc-0069/","id":"tclc-0069"},{"k":"archive","label":"The Working Press, Volume 1, Issue 7, November 1998","sub":"Labor Coalition records · November 1998 · Newsletter","href":"../tclc/items/tclc-0071/","id":"tclc-0071"}],"thumb":"../tclc/media/thumb/b1-275.webp","note":null},{"id":"paras-campaign","date":"2001","sort":"2001-06-30","year":2001,"label":"2001–2002","era":"council","title":"A living wage for school paraprofessionals","summary":"The Ithaca Paraprofessionals Association and the Living Wage Coalition turn an 18-month contract fight into a community campaign, and win.","body":["About 220 teacher aides, assistants and bus monitors, mostly women, started at $6.72 an hour. More than 2,000 people signed a petition. A November 2001 \"Parade for Paras\" drew some 500 marchers from fifty groups. Debbie Minnick, the local’s president, first raised the idea with Carl Feuer in fall 2000.","The contract settled in June 2002 with starting pay up about 50 percent over three years. Aides went from $6.72 to $10.05 by the third year. Dollars & Sense later listed it among ten campaigns to learn from."],"themes":["wages","contracts"],"orgs":["tcwc","public","tclc"],"sources":[{"k":"archive","label":"Union City News, Midstate Central Labor Council, September 2002","sub":"Labor Coalition records · September 2002 · Newsletter","href":"../tclc/items/tclc-0022/","id":"tclc-0022"},{"k":"doc","label":"Carl Feuer and Pete Meyers, “Solidarity in One Community: How Worker Centers Can Work with Organized Labor,” Tompkins County Workers' Center case study","sub":null,"href":null},{"k":"doc","label":"Tompkins County Workers' Center, organizational history chronology (unpublished draft); dated public events only","sub":null,"href":null}],"thumb":"../tclc/media/thumb/b1-074.webp","note":null},{"id":"northwoods","date":"2001-12-14","sort":"2001-12-14","year":2001,"label":"December 14, 2001","era":"council","title":"Carols at Northwoods Nursing Home","summary":"About 50 people sing union carols in the rain outside a Cortland nursing home where some 160 workers are trying to join CSEA.","body":["Management had told workers to remove union buttons. At least 12 locals from three labor councils came, along with the Living Wage Coalition and Cornell students. The December 28 election was postponed after charges were filed against management."],"themes":["organizing"],"orgs":["tclc","public","tcwc"],"sources":[{"k":"archive","label":"Street Heat: December Events for Union Activists [December 2001]","sub":"Labor Coalition records · December [2001] · Newsletter","href":"../tclc/items/tclc-0025/","id":"tclc-0025"},{"k":"archive","label":"Union City News, Midstate Central Labor Council, January [2002]","sub":"Labor Coalition records · January [2002] · Newsletter","href":"../tclc/items/tclc-0019/","id":"tclc-0019"}],"thumb":"../tclc/media/thumb/b1-083.webp","note":null},{"id":"luster-retires","date":"2002-03","sort":"2002-03-15","year":2002,"label":"March 2002","era":"council","title":"Goodbye, Marty Luster","summary":"Assembly member Marty Luster, a past Friend of Labor with a 100 percent union voting record, announces his retirement.","body":["The council pointed out that union households were 26 percent of voters in 2000 and started recruiting members for phone banks and voter registration."],"themes":["politics"],"orgs":["tclc"],"sources":[{"k":"archive","label":"Union City News, Midstate Central Labor Council, March 2002","sub":"Labor Coalition records · March 2002 · Newsletter","href":"../tclc/items/tclc-0026/","id":"tclc-0026"}],"thumb":"../tclc/media/thumb/b1-085.webp","note":null},{"id":"living-wage-staff","date":"2002","sort":"2002-06-30","year":2002,"label":"2002","era":"council","title":"The Living Wage Coalition hires Pete Meyers and Carl Feuer","summary":"With a grant from the Center for Religion, Ethics and Social Policy at Cornell, the coalition hires two organizers to share one full-time job.","body":["The coalition also joined the new Tompkins County Religious Task Force for a Living Wage, part of the state Labor-Religion Coalition. A Business Task Force looked for local employers that already paid a living wage."],"themes":["wages","founding"],"orgs":["tcwc"],"sources":[{"k":"doc","label":"Tompkins County Workers' Center, organizational history chronology (unpublished draft); dated public events only","sub":null,"href":null}],"thumb":null,"note":null},{"id":"picnic-2002","date":"2002-09-02","sort":"2002-09-02","year":2002,"label":"September 2, 2002","era":"council","title":"\"Labor and the Community Working Together for a Living Wage\"","summary":"The 19th Labor Day picnic is co-sponsored by the Labor Coalition and the Midstate council, which then represented some forty unions and more than 8,000 workers.","body":["The Union City News issue carried Debbie Minnick’s account of the paraprofessionals’ win and congratulated workers at Lakeside Nursing Home, who forced a settlement on the verge of a walkout and won raises of over 30 percent for the lowest paid."],"themes":["laborday","wages"],"orgs":["tclc","tcwc"],"sources":[{"k":"archive","label":"Union City News, Midstate Central Labor Council, September 2002","sub":"Labor Coalition records · September 2002 · Newsletter","href":"../tclc/items/tclc-0022/","id":"tclc-0022"},{"k":"archive","label":"Union City News, Midstate Central Labor Council, October 2002","sub":"Labor Coalition records · October 2002 · Newsletter","href":"../tclc/items/tclc-0021/","id":"tclc-0021"}],"thumb":"../tclc/media/thumb/b1-074.webp","note":null},{"id":"coalition-born","date":"2003-01-01","sort":"2003-01-01","year":2003,"label":"January 1, 2003","era":"center","title":"The Living Wage Coalition opens as an organization","summary":"The Tompkins County Living Wage Coalition starts work as a project of CRESP, with a budget of about $25,000 and two part-time staff.","body":["Pete Meyers wrote this date down as the Workers’ Center’s birthday when it marked ten years in 2013. In 2004 the coalition described itself as 43 labor, faith, community, student and political organizations."],"themes":["founding"],"orgs":["tcwc"],"sources":[{"k":"paper","label":"The Workers’ Edge, Winter 2012–13","sub":"Newsletter of the Tompkins County Workers’ Center","href":null},{"k":"doc","label":"Tompkins County Workers' Center, organizational history chronology (unpublished draft); dated public events only","sub":null,"href":null}],"thumb":null,"note":null},{"id":"hotline-opens","date":"2003-05","sort":"2003-05-15","year":2003,"label":"May 2003","era":"center","title":"The Workers’ Rights Hotline opens","summary":"The coalition launches a Workers Rights Center for information, referral and advocacy, modeled on the Cortland Workers Rights Board.","body":["It handled 117 cases in its first seven months, 178 in 2004 and about 250 a year by 2005. By 2013 it served more than 300 workers a year. In 2025 Pete Meyers told Tompkins Weekly that about 26 percent of all calls since May 2003, over 1,700 people, had been about firings."],"themes":["rights"],"orgs":["tcwc"],"sources":[{"k":"doc","label":"Carl Feuer and Pete Meyers, “How Can Worker Centers Work with Traditional Unions?” AFL-CIO blog, 2013","sub":null,"href":null},{"k":"paper","label":"The Workers’ Edge, Winter 2012–13","sub":"Newsletter of the Tompkins County Workers’ Center","href":null},{"k":"web","label":"Tompkins Weekly, “Ithaca moves to revive just-cause labor talks” (2026)","sub":"News and public record","href":"https://tompkinsweekly.com/?p=33097"}],"thumb":null,"note":null},{"id":"living-wage-resolutions","date":"2003-08","sort":"2003-08-15","year":2003,"label":"June–November 2003","era":"center","title":"The city and county pass living wage resolutions","summary":"Common Council passes a living wage resolution in June and the County Legislature passes one in August, 10 to 4.","body":["In November the city raised 12 permanent employees, some paid as little as $8.01, to the $8.44 living wage. The county resolution said it would \"consider wage levels and benefits\" in awarding contracts. Ten years later the coalition went back to the county to make that language mean something."],"themes":["wages","politics"],"orgs":["tcwc","gov"],"sources":[{"k":"doc","label":"Tompkins County Workers' Center, organizational history chronology (unpublished draft); dated public events only","sub":null,"href":null}],"thumb":null,"note":null},{"id":"collegetown-pizza","date":"2003-09-29","sort":"2003-09-29","year":2003,"label":"2003–2004","era":"center","title":"The Collegetown Pizza case","summary":"Working with the state attorney general, the Workers Rights Center wins back wages for three immigrant workers who described 70-hour weeks without overtime.","body":["Five Cornell student groups joined a September 29, 2003 press conference. The April 2004 settlement paid more than $7,000 and required the restaurant to post a bilingual notice of workers’ rights and give paid leave."],"themes":["rights"],"orgs":["tcwc","students"],"sources":[{"k":"doc","label":"Tompkins County Workers' Center, organizational history chronology (unpublished draft); dated public events only","sub":null,"href":null}],"thumb":null,"note":null},{"id":"autumn-leaves","date":"2004-01","sort":"2004-01-15","year":2004,"label":"January 2004","era":"center","title":"An office above Autumn Leaves","summary":"The coalition moves into the second floor above Autumn Leaves Books on the Commons and rents space to other small groups.","body":["The space became known as a peace and justice center, with a small incubator for other groups funded in 2005."],"themes":["founding"],"orgs":["tcwc"],"sources":[{"k":"doc","label":"Tompkins County Workers' Center, organizational history chronology (unpublished draft); dated public events only","sub":null,"href":null}],"thumb":null,"note":null},{"id":"kinkos","date":"2004-03-25","sort":"2004-03-25","year":2004,"label":"March 2004","era":"center","title":"Kinko’s owes its workers more than $20,000","summary":"After a complaint filed in August 2002 and help from Rep. Maurice Hinchey, the U.S. Department of Labor finds Kinko’s altered time records.","body":["Six employees received more than $20,000. Workers said they were told to punch out and keep working."],"themes":["rights"],"orgs":["tcwc"],"sources":[{"k":"doc","label":"Tompkins County Workers' Center, organizational history chronology (unpublished draft); dated public events only","sub":null,"href":null}],"thumb":null,"note":null},{"id":"state-minimum-2004","date":"2004-12-06","sort":"2004-12-06","year":2004,"label":"December 6, 2004","era":"center","title":"New York raises the minimum wage over Pataki’s veto","summary":"The State Senate joins the Assembly in overriding the governor. The minimum wage rises in steps from $5.15 to $7.15 by 2007.","body":["Locally the coalition rallied 200 people on April 3, 2004, ending in front of the Holiday Inn, and brought business owners to the County Legislature. \"The movement for economic justice unites people across the political divide,\" Carl Feuer said."],"themes":["wages","politics"],"orgs":["tcwc"],"sources":[{"k":"doc","label":"Tompkins County Workers' Center, organizational history chronology (unpublished draft); dated public events only","sub":null,"href":null}],"thumb":null,"note":null},{"id":"walmart-campaign","date":"2005-01","sort":"2005-01-15","year":2005,"label":"2005","era":"center","title":"The Wal-Mart Living Wage campaign","summary":"As a new Wal-Mart opens in Ithaca, the coalition gathers more than 5,000 signatures asking for a living wage of $9.18 an hour with health insurance.","body":["Twenty-nine religious leaders signed a letter to the store. The campaign ran billboards, Pennysaver ads, a bumper sticker reading \"A Living Wage is a Moral Value,\" and a week of showings of \"The High Cost of Low Prices.\" Petitions were delivered on November 17, 2005."],"themes":["wages"],"orgs":["tcwc"],"sources":[{"k":"doc","label":"Tompkins County Workers' Center, organizational history chronology (unpublished draft); dated public events only","sub":null,"href":null}],"thumb":null,"note":null},{"id":"immigrant-rights-center","date":"2005","sort":"2005-06-30","year":2005,"label":"2005","era":"center","title":"An Immigrant Rights Center","summary":"The coalition starts an Immigrant Rights Center with the Latino Civic Association and the Ithaca Asian-American Association.","body":["It promised outreach in Spanish, Mandarin, Russian and Korean. On May 1, 2006 a weekday rally for immigrant rights on the Commons drew a very large crowd."],"themes":["rights","politics"],"orgs":["tcwc"],"sources":[{"k":"doc","label":"Tompkins County Workers' Center, organizational history chronology (unpublished draft); dated public events only","sub":null,"href":null}],"thumb":null,"note":null},{"id":"lw-certification","date":"2006","sort":"2006-06-30","year":2006,"label":"2006","era":"center","title":"The first Living Wage Employer Certification","summary":"The coalition certifies employers who pay at least the Tompkins County living wage, the first program of its kind in the country.","body":["It was modeled on Fair Trade certification and used the living wage that Alternatives Federal Credit Union had calculated since 1994. GreenStar, which adopted its own living wage in 2004, and Tompkins County, with more than 750 workers, were early members. Interfaith Worker Justice later promoted the model nationally.","By spring 2019 there were 119 certified employers with more than 3,000 workers."],"themes":["wages"],"orgs":["tcwc","gov"],"sources":[{"k":"doc","label":"Tompkins County Workers' Center, organizational history chronology (unpublished draft); dated public events only","sub":null,"href":null},{"k":"doc","label":"Carl Feuer and Pete Meyers, “Solidarity in One Community: How Worker Centers Can Work with Organized Labor,” Tompkins County Workers' Center case study","sub":null,"href":null},{"k":"paper","label":"The Workers’ Edge, Spring 2019","sub":"Newsletter of the Tompkins County Workers’ Center","href":null},{"k":"web","label":"Cornell ILR News, “Many in Tompkins County do not earn a living wage”","sub":"News and public record","href":"https://www.ilr.cornell.edu/news/research/many-tompkins-county-do-not-earn-living-wage-ilr-researchers"}],"thumb":null,"note":null},{"id":"name-change","date":"2006-08","sort":"2006-08-15","year":2006,"label":"August 2006","era":"center","title":"The name becomes the Tompkins County Workers’ Center","summary":"The Living Wage Coalition, Workers’ Rights Center and Immigrant Rights Center take one name.","body":["The same year the Workers’ Center became co-organizer of the Labor Day picnic with the Midstate Central Labor Council."],"themes":["founding","laborday"],"orgs":["tcwc","tclc"],"sources":[{"k":"doc","label":"Tompkins County Workers' Center, organizational history chronology (unpublished draft); dated public events only","sub":null,"href":null},{"k":"doc","label":"Carl Feuer and Pete Meyers, “Solidarity in One Community: How Worker Centers Can Work with Organized Labor,” Tompkins County Workers' Center case study","sub":null,"href":null}],"thumb":null,"note":null},{"id":"unemployment-reform","date":"2006-12","sort":"2006-12-15","year":2006,"label":"2006–2007","era":"center","title":"Unemployment insurance for school-year workers","summary":"UAW Local 2300 and the Workers’ Center push to let seasonally laid-off school and college workers collect unemployment.","body":["Assemblywoman Barbara Lifton joined a December press conference. The Ithaca Common Council, the Town of Ithaca and the County Legislature passed supporting resolutions. The statewide campaign did not succeed."],"themes":["politics"],"orgs":["tcwc","uaw2300","gov"],"sources":[{"k":"doc","label":"Carl Feuer and Pete Meyers, “Solidarity in One Community: How Worker Centers Can Work with Organized Labor,” Tompkins County Workers' Center case study","sub":null,"href":null}],"thumb":null,"note":null},{"id":"workers-edge-launch","date":"2007","sort":"2007-06-30","year":2007,"label":"Spring 2007","era":"center","title":"The Workers’ Edge","summary":"The Workers’ Center’s newsletter, \"Voice of the Tompkins County Workers’ Center,\" leads with how the hotline turns complaints into organizing.","body":["The lead story told how Greg Evans, a line cook near the Commons facing racist comments and cut hours, came to the center in February and got his hours back. Members paid one hour’s wage a year in dues and promised to show up five times a year for other people’s fights."],"themes":["press","rights"],"orgs":["tcwc"],"sources":[{"k":"paper","label":"The Workers’ Edge, Spring 2007","sub":"Newsletter of the Tompkins County Workers’ Center","href":null}],"thumb":null,"note":null},{"id":"rimland-hotel","date":"2007","sort":"2007-06-30","year":2007,"label":"2007–2008","era":"center","title":"A living wage for downtown hotel housekeepers","summary":"Developer Jeffrey Rimland agrees to pay housekeepers at a planned Commons hotel the $11.18 living wage, but not all employees.","body":["The Ithaca Journal opposed the Workers’ Center but wrote that the living wage was \"a consistent topic in every economic development discussion in Ithaca.\""],"themes":["wages"],"orgs":["tcwc","gov"],"sources":[{"k":"doc","label":"Tompkins County Workers' Center, organizational history chronology (unpublished draft); dated public events only","sub":null,"href":null}],"thumb":null,"note":null},{"id":"hilton-garden","date":"2007-10","sort":"2007-10-15","year":2007,"label":"October 2007","era":"center","title":"An NLRB charge for a Hilton Garden Inn housekeeper","summary":"The Workers’ Center files an unfair labor practice charge for Michelle Lopez, fired after speaking up for co-workers. About 100 people demonstrate at the hotel in November.","body":["The NLRB did not find the firing was for union activity, but it upheld part of the charge and required the hotel to post a notice for 60 days about the right to organize."],"themes":["rights","organizing"],"orgs":["tcwc"],"sources":[{"k":"doc","label":"Carl Feuer and Pete Meyers, “Solidarity in One Community: How Worker Centers Can Work with Organized Labor,” Tompkins County Workers' Center case study","sub":null,"href":null}],"thumb":null,"note":null},{"id":"plum-tree","date":"2008","sort":"2008-06-30","year":2008,"label":"2008","era":"center","title":"$6,800 for restaurant workers, without the state","summary":"The Workers’ Center negotiates back wages and tips for 10 workers at Plum Tree and Sushi O Sake, a settlement reached with no government agency involved.","body":["That October the state Department of Labor found $28,388 owed to 36 workers at Taste of Thai and Tamarind."],"themes":["rights"],"orgs":["tcwc"],"sources":[{"k":"doc","label":"Tompkins County Workers' Center, organizational history chronology (unpublished draft); dated public events only","sub":null,"href":null}],"thumb":null,"note":null},{"id":"cuo-model","date":"2008","sort":"2008-06-30","year":2008,"label":"2008","era":"center","title":"Community Union Organizers","summary":"The Workers’ Center develops a Community Union Organizer program, treating the whole county as its \"bargaining unit.\"","body":["Early organizers helped plan May Day, recover back wages, start an unemployed workers’ support group, and organize at Cost Cutters and the Ithaca Coffee Company. Labor Notes educator Ellen David Friedman later worked with the center to rebuild the program."],"themes":["organizing"],"orgs":["tcwc"],"sources":[{"k":"paper","label":"The Workers’ Edge, Spring 2010","sub":"Newsletter of the Tompkins County Workers’ Center","href":null},{"k":"paper","label":"The Workers’ Edge, Spring 2019","sub":"Newsletter of the Tompkins County Workers’ Center","href":null},{"k":"doc","label":"Tompkins County Workers' Center, strategic plan pillars brief","sub":null,"href":null}],"thumb":null,"note":null},{"id":"lakeside-2008","date":"2008-12","sort":"2008-12-15","year":2008,"label":"Winter 2008–09","era":"center","title":"\"Caregivers Deserve Better!\" at Lakeside","summary":"The Workers’ Center and Families and Friends of Lakeside back about 140 SEIU 1199 nursing home workers who had gone three years without a raise.","body":["At least a third earned less than the $9.83 living wage. Over 100 people joined an informational picket on a bitter winter weekend. A Workers’ Center member who lived at the home helped organize residents and families. The contract settled on terms the workers sought. When new owners tried to make every union worker reapply in 2010, the center campaigned again."],"themes":["contracts","wages"],"orgs":["tcwc","private"],"sources":[{"k":"paper","label":"The Workers’ Edge, Winter 2008","sub":"Newsletter of the Tompkins County Workers’ Center","href":null},{"k":"doc","label":"Carl Feuer and Pete Meyers, “Solidarity in One Community: How Worker Centers Can Work with Organized Labor,” Tompkins County Workers' Center case study","sub":null,"href":null}],"thumb":null,"note":null},{"id":"regis","date":"2009-02","sort":"2009-02-15","year":2009,"label":"2009–2010","era":"community","title":"Regis and the \"yellow dog\" contract","summary":"A fired Cost Cutters stylist leads the Workers’ Center to a Regis Corporation agreement that made workers give up any future union card.","body":["Amber Little was fired for not selling enough product. Regis called its document a \"Protection of Secret Vote Agreement.\" The center rallied in front of the salon, sent more than 400 faxes, and filed with the NLRB. After it contacted the Minneapolis Star-Tribune, the story ran on the front page in Regis’s home town.","In October 2010 the NLRB upheld the complaint, and Regis had to tell its workers nationwide about their right to organize. The Labor Day picnic named Regis the Goat of Labor in 2011."],"themes":["rights","organizing"],"orgs":["tcwc"],"sources":[{"k":"doc","label":"Carl Feuer and Pete Meyers, “Solidarity in One Community: How Worker Centers Can Work with Organized Labor,” Tompkins County Workers' Center case study","sub":null,"href":null},{"k":"paper","label":"The Workers’ Edge, Spring 2010","sub":"Newsletter of the Tompkins County Workers’ Center","href":null},{"k":"paper","label":"The Workers’ Edge, Fall 2011","sub":"Newsletter of the Tompkins County Workers’ Center","href":null}],"thumb":null,"note":null},{"id":"efca","date":"2009-04-07","sort":"2009-04-07","year":2009,"label":"April 7, 2009","era":"community","title":"The county backs the Employee Free Choice Act","summary":"After a rally of more than 100 people at the courthouse, the County Legislature passes a resolution supporting EFCA, 12 to 3.","body":["The Midstate Central Labor Council co-sponsored the rally. Kate Bronfenbrenner, Pete Meyers and former Assemblyman Marty Luster spoke, and six legislators explained their votes."],"themes":["politics","organizing"],"orgs":["tcwc","tclc","gov"],"sources":[{"k":"doc","label":"Carl Feuer and Pete Meyers, “Solidarity in One Community: How Worker Centers Can Work with Organized Labor,” Tompkins County Workers' Center case study","sub":null,"href":null}],"thumb":null,"note":null},{"id":"afl-cio-affiliation","date":"2009","sort":"2009-06-30","year":2009,"label":"2009","era":"community","title":"The Workers’ Center affiliates with the AFL-CIO","summary":"Under a 2006 AFL-CIO resolution, the Workers’ Center becomes one of the first worker centers formally affiliated with the labor federation.","body":["By 2013 there were 18 such local affiliations nationally. The Tompkins center was more rural than most and was not primarily an immigrant workers’ group."],"themes":["founding","solidarity"],"orgs":["tcwc","tclc"],"sources":[{"k":"doc","label":"Carl Feuer and Pete Meyers, “Solidarity in One Community: How Worker Centers Can Work with Organized Labor,” Tompkins County Workers' Center case study","sub":null,"href":null}],"thumb":null,"note":null},{"id":"ohcc","date":"2009","sort":"2009-06-30","year":2009,"label":"Spring 2009","era":"community","title":"Care for injured workers","summary":"The Workers’ Center partners with the Occupational Health Clinical Center in Syracuse, which sees injured and sick workers regardless of immigration status.","body":["Linda Holzbaur wrote the Workers’ Edge story on getting injured workers the care they were owed."],"themes":["safety"],"orgs":["tcwc"],"sources":[{"k":"paper","label":"The Workers’ Edge, Spring 2009","sub":"Newsletter of the Tompkins County Workers’ Center","href":null}],"thumb":null,"note":null},{"id":"restaurant-sweep","date":"2009-12","sort":"2009-12-15","year":2009,"label":"2009","era":"community","title":"The state sweeps Ithaca restaurants","summary":"At the Workers’ Center’s urging, the Department of Labor inspects 22 restaurants and finds about $88,000 owed to 93 workers.","body":["Labor Commissioner Patricia Smith announced the results with the Workers’ Center in December. \"To them I say thank you,\" she said of employers who played by the rules. In 2010 the state assessed nearly $1 million against the owner of the Green Café in Ithaca and New York City."],"themes":["rights"],"orgs":["tcwc","gov"],"sources":[{"k":"paper","label":"The Workers’ Edge, Winter 2010","sub":"Newsletter of the Tompkins County Workers’ Center","href":null},{"k":"doc","label":"Tompkins County Workers' Center, organizational history chronology (unpublished draft); dated public events only","sub":null,"href":null}],"thumb":null,"note":null},{"id":"coffee-union","date":"2010-02-21","sort":"2010-02-21","year":2010,"label":"February 21, 2010","era":"community","title":"The Tompkins County Coffee Workers Union","summary":"Eight of 11 non-managerial workers at the Ithaca Coffee Company sign a petition to form an independent union. \"Fair Trade from Bean to Cup.\"","body":["The company refused recognition and hired an anti-union firm. With support weakening, the workers withdrew their petition two days before the April 21 NLRB vote. The center drew a lesson about the limits of the NLRB process."],"themes":["organizing"],"orgs":["tcwc"],"sources":[{"k":"paper","label":"The Workers’ Edge, Spring 2010","sub":"Newsletter of the Tompkins County Workers’ Center","href":null},{"k":"doc","label":"Carl Feuer and Pete Meyers, “Solidarity in One Community: How Worker Centers Can Work with Organized Labor,” Tompkins County Workers' Center case study","sub":null,"href":null}],"thumb":null,"note":null},{"id":"one-nation","date":"2010-10-02","sort":"2010-10-02","year":2010,"label":"October 2010","era":"community","title":"Three buses to One Nation in Washington","summary":"The Workers’ Center fills three buses for the One Nation rally for jobs. UAW pays for buses and lunches.","body":["In 2008 the two had filled a bus to Atlantic City for UAW casino workers."],"themes":["solidarity"],"orgs":["tcwc","uaw2300"],"sources":[{"k":"doc","label":"Carl Feuer and Pete Meyers, “Solidarity in One Community: How Worker Centers Can Work with Organized Labor,” Tompkins County Workers' Center case study","sub":null,"href":null}],"thumb":null,"note":null},{"id":"sodexo","date":"2011","sort":"2011-06-30","year":2011,"label":"Spring 2011","era":"community","title":"A living wage for Sodexo workers at Ithaca College","summary":"Students in LIPS and the Workers’ Center win the $11.67 living wage for more than 120 food service workers, some of whom made $8.19.","body":["Kiera Lewis, a former Workers’ Center intern, founded Labor Initiative in Promoting Solidarity in fall 2010 after SEIU stepped back from organizing. \"This is a huge victory, but it is just a first step,\" she said. The students won the Joe Hill Award that Labor Day."],"themes":["wages"],"orgs":["tcwc","students"],"sources":[{"k":"paper","label":"The Workers’ Edge, Spring 2011","sub":"Newsletter of the Tompkins County Workers’ Center","href":null},{"k":"doc","label":"Tompkins County Workers' Center, organizational history chronology (unpublished draft); dated public events only","sub":null,"href":null}],"thumb":null,"note":null},{"id":"restaurant-manual","date":"2011","sort":"2011-06-30","year":2011,"label":"2011","era":"community","title":"A Restaurant Owners Manual","summary":"The Workers’ Center publishes a plain guide to labor law for restaurant owners, with the Chamber of Commerce, the county and the Department of Labor.","body":["The county Health Department distributed it."],"themes":["rights"],"orgs":["tcwc","gov"],"sources":[{"k":"paper","label":"The Workers’ Edge, Winter 2012–13","sub":"Newsletter of the Tompkins County Workers’ Center","href":null},{"k":"doc","label":"Tompkins County Workers' Center, organizational history chronology (unpublished draft); dated public events only","sub":null,"href":null}],"thumb":null,"note":null},{"id":"labor-day-2011","date":"2011-09-05","sort":"2011-09-05","year":2011,"label":"Labor Day 2011","era":"community","title":"Labor Day 2011: two Goats","summary":"Awards chosen by the labor council and the Workers’ Center go to Jamie Dangler of UUP, the LIPS students, Pastor Rich Rose, and Theresa Alt. The Goats go to Regis and Governor Andrew Cuomo.","body":["Rain moved the picnic inside the large pavilion. The Evil City String Band played. Neither Goat came to collect."],"themes":["laborday"],"orgs":["tcwc","tclc","students"],"sources":[{"k":"paper","label":"The Workers’ Edge, Fall 2011","sub":"Newsletter of the Tompkins County Workers’ Center","href":null}],"thumb":null,"note":null},{"id":"occupy","date":"2011-10-05","sort":"2011-10-05","year":2011,"label":"October 2011","era":"community","title":"Occupy Ithaca","summary":"The Workers’ Center asks what Occupy Wall Street means for local workers, as Occupy Ithaca rallies on October 5.","body":["Occupy Ithaca received the Mother Jones Award at the 2012 picnic."],"themes":["politics","solidarity"],"orgs":["tcwc"],"sources":[{"k":"paper","label":"The Workers’ Edge, Fall 2011","sub":"Newsletter of the Tompkins County Workers’ Center","href":null},{"k":"paper","label":"The Workers’ Edge, Winter 2012–13","sub":"Newsletter of the Tompkins County Workers’ Center","href":null}],"thumb":null,"note":null},{"id":"upstate-alliance","date":"2012-06","sort":"2012-06-15","year":2012,"label":"2012","era":"community","title":"An Upstate New York Workers’ Center Alliance","summary":"With Interfaith Worker Justice funding, the Tompkins center starts regular meetings with new worker centers in Syracuse, Rochester, Buffalo, Lyons and Kingston.","body":["The center described its role as guiding newer centers as they formed."],"themes":["solidarity","organizing"],"orgs":["tcwc"],"sources":[{"k":"paper","label":"The Workers’ Edge, Winter 2012–13","sub":"Newsletter of the Tompkins County Workers’ Center","href":null},{"k":"doc","label":"Carl Feuer and Pete Meyers, “How Can Worker Centers Work with Traditional Unions?” AFL-CIO blog, 2013","sub":null,"href":null}],"thumb":null,"note":null},{"id":"min-wage-living-wage-2012","date":"2012","sort":"2012-06-30","year":2012,"label":"Spring 2012","era":"community","title":"\"Make the Minimum Wage a Living Wage\"","summary":"As Albany debates $8.50, the Workers’ Center argues the minimum should be the $12.78 county living wage, and puts up yard signs.","body":["Pete Meyers testified at a state Senate Democratic hearing in April 2012. Mayor Svante Myrick then worked quietly with the center to bring about 50 seasonal and temporary city workers up to the living wage, and the City of Ithaca became the center’s 93rd certified employer."],"themes":["wages","politics"],"orgs":["tcwc","gov"],"sources":[{"k":"paper","label":"The Workers’ Edge, Spring 2012","sub":"Newsletter of the Tompkins County Workers’ Center","href":null},{"k":"doc","label":"Tompkins County Workers' Center, organizational history chronology (unpublished draft); dated public events only","sub":null,"href":null}],"thumb":null,"note":null},{"id":"labor-day-2012","date":"2012-09-03","sort":"2012-09-03","year":2012,"label":"September 3, 2012","era":"community","title":"\"We Are the 99%\": the 29th picnic","summary":"More than 400 people attend. Rep. Maurice Hinchey, retiring after 20 years, gets a special award, and Linda Smith is Friend of Labor.","body":["Smith had co-founded the Cortland Workers Rights Board, led UAW Local 1326 at Pall Trinity, and served as president of the Midstate council. The Goat went to the Newfield School District for not bargaining in good faith with its teachers."],"themes":["laborday"],"orgs":["tcwc","tclc"],"sources":[{"k":"paper","label":"The Workers’ Edge, Winter 2012–13","sub":"Newsletter of the Tompkins County Workers’ Center","href":null}],"thumb":null,"note":null},{"id":"tca-union","date":"2013-01","sort":"2013-01-15","year":2013,"label":"January 2013","era":"community","title":"Tompkins Community Action workers win a union","summary":"Workers who first called the hotline in 2012 organize \"Tompkins Community Reaction,\" affiliate with the Painters’ District Council 4, and win their election.","body":["The unit of more than 70 Head Start aides, energy services, family and housing staff voted in January. Over 100 people celebrated at the center’s office. TCWC sat in on bargaining and was ready to threaten the agency’s Living Wage certification before a first contract was reached.","Around the same time 35 staff at New Roots Charter School won voluntary recognition with NYSUT after the center connected them."],"themes":["organizing","contracts"],"orgs":["tcwc","private","public"],"sources":[{"k":"doc","label":"Carl Feuer and Pete Meyers, “Solidarity in One Community: How Worker Centers Can Work with Organized Labor,” Tompkins County Workers' Center case study","sub":null,"href":null},{"k":"doc","label":"Carl Feuer and Pete Meyers, “How Can Worker Centers Work with Traditional Unions?” AFL-CIO blog, 2013","sub":null,"href":null}],"thumb":null,"note":null},{"id":"ten-years","date":"2013","sort":"2013-06-30","year":2013,"label":"2013","era":"community","title":"Ten years, and a first Annual Giving Campaign","summary":"Marking its tenth year, the Workers’ Center reports a budget near $125,000, up from $25,000, and launches annual giving as a national church grant ends.","body":["The 2013 campaign raised $58,000 from local supporters. Former Mayor Carolyn Peterson led the second year."],"themes":["founding"],"orgs":["tcwc"],"sources":[{"k":"paper","label":"The Workers’ Edge, Winter 2012–13","sub":"Newsletter of the Tompkins County Workers’ Center","href":null},{"k":"paper","label":"The Workers’ Edge, Spring 2014","sub":"Newsletter of the Tompkins County Workers’ Center","href":null}],"thumb":null,"note":null},{"id":"county-contractors","date":"2013-12","sort":"2013-12-15","year":2013,"label":"2013–2015","era":"community","title":"A living wage for county contract workers","summary":"Recycling workers Milton Webb and Stanley McPherson, paid $8 an hour, lead a campaign that ends with a $100,000 county living wage fund.","body":["More than 1,000 residents petitioned. Webb and McPherson started their own cable access show. County Administrator Joe Mareane convened a working group that met at least ten times. In December 2013 the Legislature approved the fund proposed by Carol Chock and Nate Shinagawa.","On January 6, 2015 the Legislature voted 14 to 0 to send $20,000 to Casella, which raised recycling center workers to the living wage on February 1."],"themes":["wages","politics"],"orgs":["tcwc","gov"],"sources":[{"k":"paper","label":"The Workers’ Edge, Fall 2013","sub":"Newsletter of the Tompkins County Workers’ Center","href":null},{"k":"doc","label":"Tompkins County Workers' Center, organizational history chronology (unpublished draft); dated public events only","sub":null,"href":null}],"thumb":null,"note":null},{"id":"workers-memorial-2014","date":"2014-04-28","sort":"2014-04-28","year":2014,"label":"April 28, 2014","era":"community","title":"Workers Memorial Day for Francisco Ortiz","summary":"Midstate COSH, the Workers’ Center and farmworker groups remember a dairy worker killed on a farm near Ithaca in February 2013.","body":["José Cañas of the Justice for Dairy Farmworkers campaign spoke, and the OSHA area director described new inspections of New York dairy farms beginning that July. UAW Local 2300 also moved its office that spring from Geneva Street to Hanshaw Road."],"themes":["safety","solidarity"],"orgs":["tcwc","uaw2300"],"sources":[{"k":"paper","label":"The Workers’ Edge, Spring 2014","sub":"Newsletter of the Tompkins County Workers’ Center","href":null}],"thumb":null,"note":null},{"id":"countywide-min-wage","date":"2015","sort":"2015-06-30","year":2015,"label":"2015","era":"county","title":"A countywide minimum wage that is a living wage","summary":"The Workers’ Center launches a campaign for every worker in the county to earn the living wage, then $14.34.","body":["The plan was to win a county law first, then approval in Albany. Registered nurses at Cayuga Medical Center began organizing with 1199SEIU that year, and part-time contingent faculty at Ithaca College formed a union."],"themes":["wages","organizing"],"orgs":["tcwc","private","students"],"sources":[{"k":"paper","label":"The Workers’ Edge, Spring 2015","sub":"Newsletter of the Tompkins County Workers’ Center","href":null},{"k":"paper","label":"The Workers’ Edge, Fall 2016","sub":"Newsletter of the Tompkins County Workers’ Center","href":null}],"thumb":null,"note":null},{"id":"wheres-our-250","date":"2016-04","sort":"2016-04-15","year":2016,"label":"April 2016","era":"county","title":"\"Where’s OUR $2.50?\"","summary":"New York passes a $15 minimum wage for New York City and $12.50 upstate. The Workers’ Center applauds and asks why upstate gets less.","body":["A Living Wage Working Group with unionists, employers, agencies, officials and Cornell’s Ian Greer began studying a county wage."],"themes":["wages","politics"],"orgs":["tcwc"],"sources":[{"k":"paper","label":"The Workers’ Edge, Spring 2016","sub":"Newsletter of the Tompkins County Workers’ Center","href":null}],"thumb":null,"note":null},{"id":"verizon-strike","date":"2016-05","sort":"2016-05-15","year":2016,"label":"May 2016","era":"county","title":"Verizon workers win","summary":"The Workers’ Center organizes regular picket support for CWA during the Verizon strike.","body":["Supporters included Cayuga Medical Center nurses, Cornell grad students, COLA, the Catholic Worker, IC adjuncts, the Ithaca Teachers Association, and TC3 adjuncts."],"themes":["strikes","solidarity"],"orgs":["tcwc","private","students"],"sources":[{"k":"paper","label":"The Workers’ Edge, Spring 2016","sub":"Newsletter of the Tompkins County Workers’ Center","href":null}],"thumb":null,"note":null},{"id":"ic-contingent","date":"2016","sort":"2016-06-30","year":2016,"label":"2016–17","era":"county","title":"IC contingent faculty win a first contract","summary":"Ithaca College’s part-time contingent faculty, organized in 2015, win their first contract.","body":["Tom Schneller of the bargaining committee wrote that it began with a meeting at Gimme! Coffee on a dark January afternoon."],"themes":["contracts","organizing"],"orgs":["students","private"],"sources":[{"k":"paper","label":"The Workers’ Edge, issue of 2016–17","sub":"Newsletter of the Tompkins County Workers’ Center","href":null}],"thumb":null,"note":null},{"id":"labor-day-2016","date":"2016-09-05","sort":"2016-09-05","year":2016,"label":"Labor Day 2016","era":"county","title":"Labor Day 2016: CMC is the Goat","summary":"More than 500 people come to the 33rd picnic. Cayuga Medical Center is named Goat of Labor over its fight with nurses, and Paula Burke is honored posthumously as Friend of Labor.","body":["Awards also went to Cornell Graduate Students United, helped that August by an NLRB decision treating grad students as employees, and to full-time contingent faculty at Ithaca College. A second Goat went to Hayner-Hoyt construction. The next year the picnic moved to the Cass Park pavilion."],"themes":["laborday","organizing"],"orgs":["tcwc","tclc","students"],"sources":[{"k":"paper","label":"The Workers’ Edge, Fall 2016","sub":"Newsletter of the Tompkins County Workers’ Center","href":null}],"thumb":null,"note":null},{"id":"gimme","date":"2017-06-01","sort":"2017-06-01","year":2017,"label":"June 1, 2017","era":"county","title":"Gimme! Coffee baristas vote for a union","summary":"Baristas vote 16 to 1 to join Workers United Local 2833, with the Workers’ Center’s support. They believe it is the first union at a U.S. specialty coffee company.","body":["They ratified a three-year contract unanimously in December 2017 and announced it in February 2018. It included raises, paid sick days and just cause protection. The baristas voted to decertify in March 2021."],"themes":["organizing","contracts"],"orgs":["tcwc","private"],"sources":[{"k":"paper","label":"The Workers’ Edge, Summer 2017","sub":"Newsletter of the Tompkins County Workers’ Center","href":null},{"k":"web","label":"Cornell Daily Sun, “Gimme Coffee Baristas Ratify First Union Contract” (Feb. 7, 2018)","sub":"News and public record","href":"https://cornellsun.com/2018/02/07/gimme-coffee-baristas-ratify-first-union-contract-boosting-wages-with-management-support"},{"k":"web","label":"Wikipedia, “Gimme! Coffee”","sub":"News and public record","href":"https://en.wikipedia.org/wiki/Gimme!_Coffee"}],"thumb":null,"note":null},{"id":"enfield","date":"2017-06-14","sort":"2017-06-14","year":2017,"label":"June 14, 2017","era":"county","title":"Five municipalities ask the county for a living wage","summary":"The Town of Enfield joins Dryden, Caroline, and the City and Town of Ithaca in urging a countywide living wage law.","body":["Together they held 71 percent of the county’s people. Close to 100 people rallied outside the county’s Health and Human Services Committee."],"themes":["wages","politics"],"orgs":["tcwc","gov"],"sources":[{"k":"paper","label":"The Workers’ Edge, Summer 2017","sub":"Newsletter of the Tompkins County Workers’ Center","href":null}],"thumb":null,"note":null},{"id":"organizing-the-organized","date":"2017","sort":"2017-06-30","year":2017,"label":"2017","era":"county","title":"\"Organizing the Organized\" at UAW 2300","summary":"New Local 2300 president Jason David writes about moving from a service model to an organizing model and recruiting new stewards.","body":["The same summer issue covered the Tompkins County Immigrant Rights Coalition, for which the Workers’ Center served as fiscal sponsor."],"themes":["organizing"],"orgs":["uaw2300","tcwc"],"sources":[{"k":"paper","label":"The Workers’ Edge, Summer 2017","sub":"Newsletter of the Tompkins County Workers’ Center","href":null}],"thumb":null,"note":null},{"id":"living-wage-working-group","date":"2018","sort":"2018-06-30","year":2018,"label":"2018","era":"county","title":"A working group studies the barriers","summary":"Ian Greer reports that Tompkins County has higher income inequality than anywhere else upstate, and that its low-wage workers are disproportionately women, Hispanic and Black.","body":["The group asked how nonprofits would pay for raises, how small businesses would adapt, and what would happen to workers just above the line."],"themes":["wages"],"orgs":["tcwc","students"],"sources":[{"k":"paper","label":"The Workers’ Edge, Spring 2018","sub":"Newsletter of the Tompkins County Workers’ Center","href":null}],"thumb":null,"note":null},{"id":"troublemakers","date":"2019-03-23","sort":"2019-03-23","year":2019,"label":"March 2019","era":"county","title":"Troublemakers take over Tompkins","summary":"The Workers’ Center and Labor Notes hold a Troublemakers School at the Plumbers and Steamfitters hall. The room is standing-room only.","body":["Workshops covered mapping power, organizing in high-turnover jobs, fighting wage theft and winning living wages. Speakers included the Gimme! baristas and UE Local 506, fresh from a nine-day strike at Erie’s locomotive plant."],"themes":["organizing","solidarity"],"orgs":["tcwc","private"],"sources":[{"k":"paper","label":"The Workers’ Edge, Spring 2019","sub":"Newsletter of the Tompkins County Workers’ Center","href":null}],"thumb":null,"note":null},{"id":"excluded-workers","date":"2021","sort":"2021-06-30","year":2021,"label":"2020–2021","era":"now","title":"The Excluded Workers Fund","summary":"After New York creates a $2.1 billion fund for workers shut out of pandemic aid, the Workers’ Center helps people in Tompkins County apply.","body":["Approved applicants received about $15,600, equal to $300 a week for a year. Cecilia Faringer-Perez led the outreach. The Winter 2021 Workers’ Edge listed a larger staff, including an Excluded Workers Fund assistant."],"themes":["rights","politics"],"orgs":["tcwc"],"sources":[{"k":"paper","label":"The Workers’ Edge, Winter 2021","sub":"Newsletter of the Tompkins County Workers’ Center","href":null}],"thumb":null,"note":null},{"id":"cayuga-ridge","date":"2021","sort":"2021-06-30","year":2021,"label":"Winter 2021","era":"now","title":"Standing with Cayuga Ridge workers","summary":"The Workers’ Center backs nursing and rehab workers at Cayuga Ridge, the former Lakeside, in a campaign for fair treatment and good care.","body":["Workers carried signs in Albany reading \"Quality Care & Good Jobs for All.\""],"themes":["contracts"],"orgs":["tcwc","private"],"sources":[{"k":"paper","label":"The Workers’ Edge, Winter 2021","sub":"Newsletter of the Tompkins County Workers’ Center","href":null}],"thumb":null,"note":null},{"id":"living-wage-method","date":"2023-11","sort":"2023-11-15","year":2023,"label":"2023","era":"now","title":"A new method for the living wage","summary":"Cornell ILR researchers take over the living wage calculation from Alternatives, using local spending data. The figure jumps to $18.45.","body":["Alternatives had published the figure every two years from 1994 to 2021, and the Workers’ Center calculated it in 2022. The 2025 figure was $24.82."],"themes":["wages"],"orgs":["tcwc","students"],"sources":[{"k":"web","label":"Cornell ILR News, “Many in Tompkins County do not earn a living wage”","sub":"News and public record","href":"https://www.ilr.cornell.edu/news/research/many-tompkins-county-do-not-earn-living-wage-ilr-researchers"},{"k":"web","label":"Tompkins County Workers’ Center, “Living Wage Updated – Now $18.45/hour”","sub":"News and public record","href":"https://tcworkerscenter.org/2023/11/tompkins-county-living-wage-updated-now-18-45-hour"}],"thumb":null,"note":null},{"id":"just-cause-launch","date":"2024-03","sort":"2024-03-15","year":2024,"label":"March 2024","era":"now","title":"The just cause campaign begins","summary":"The Workers’ Center starts a campaign for a City of Ithaca law ending at-will employment, after Common Council names worker protections a priority.","body":["The draft would require a valid reason to fire anyone past a probationary period and set up a Workers’ Rights Commission to hear complaints. Advocates rallied on the Commons in March 2024 and outside City Hall in June 2025."],"themes":["rights","politics"],"orgs":["tcwc","gov"],"sources":[{"k":"web","label":"Ithaca Times, “Ithaca workers advocate for just cause legislation” (2024)","sub":"News and public record","href":"https://www.ithaca.com/news/ithaca/ithaca-workers-advocate-for-just-cause-legislation-to-challenge-at-will-employment-norms/article_296ec1e0-e0a9-11ee-b8d7-93213de34915.html"},{"k":"web","label":"Cornell Daily Sun, “‘You Can’t Boot Me Without Cause’” (May 2, 2024)","sub":"News and public record","href":"https://cornellsun.com/2024/05/02/you-cant-boot-me-without-cause-local-organizers-push-for-just-cause-good-cause-legislation/"}],"thumb":null,"note":null},{"id":"county-resolution-2024","date":"2024","sort":"2024-06-30","year":2024,"label":"2024","era":"now","title":"The county asks for a minimum wage study","summary":"Under Resolution 2024-144, Tompkins County asks the Cornell ILR Ithaca Co-Lab to explore a countywide minimum wage above New York’s $16.00.","body":["The study took place in 2026."],"themes":["wages","politics"],"orgs":["gov","students","tcwc"],"sources":[{"k":"site","label":"Tompkins County Minimum Wage Study (update on this site)","sub":"Elsewhere on this site","href":"../../updates/tompkins-minimum-wage-study.html"}],"thumb":null,"note":null},{"id":"just-cause-advance","date":"2025-09-17","sort":"2025-09-17","year":2025,"label":"September 17, 2025","era":"now","title":"Common Council advances just cause, 8 to 0","summary":"In front of a packed gallery, the Council votes to move just cause legislation forward to a working group and public comment.","body":["At a June council meeting Adam Hart of the Workers’ Center told members the hotline often hears from workers about unpaid wages and wrongful firing."],"themes":["rights","politics"],"orgs":["tcwc","gov"],"sources":[{"k":"web","label":"Cornell Daily Sun, “After Rally, Common Council Votes to Move Forward With Just Cause”","sub":"News and public record","href":"https://cornellsun.com/article/2025/09/after-rally-common-council-votes-to-move-forward-with-just-cause-firings-law"},{"k":"web","label":"Ithaca.com, “Advocates rally as Common Council re-establishes just-cause group”","sub":"News and public record","href":"https://www.ithaca.com/news/ithaca/advocates-rally-as-ithaca-common-council-re-establishes-just-cause-group/article_cddf8187-a3e2-44fd-acda-5f724a1776f8.html"}],"thumb":null,"note":null},{"id":"special-committee","date":"2026-02-04","sort":"2026-02-04","year":2026,"label":"February 4, 2026","era":"now","title":"A special committee on wrongful discharge","summary":"Common Council creates a Special Committee on Wrongful Discharge and Labor Protections, authorized through the end of 2026.","body":["The committee held public meetings through the summer of 2026 to gather research and testimony."],"themes":["rights","politics"],"orgs":["gov","tcwc"],"sources":[{"k":"web","label":"607 News Now, Ithaca takes another look at just cause termination","sub":"News and public record","href":"https://607newsnow.com/?p=29603"},{"k":"web","label":"WBNG, “Ithaca creates special committee on wrongful discharge”","sub":"News and public record","href":"https://www.wbng.com/2026/03/25/ithaca-creates-special-committee-wrongful-discharge-labor-protections/"}],"thumb":null,"note":null},{"id":"living-wage-2026","date":"2026-04-08","sort":"2026-04-08","year":2026,"label":"April 8, 2026","era":"now","title":"The 2026 living wage: $25.08","summary":"The Ithaca and Buffalo Co-Labs and the Workers’ Center release the 2026 living wage report, 32 years after Alternatives published the first one.","body":["The figure for a single full-time worker is $25.08 an hour."],"themes":["wages"],"orgs":["tcwc","students"],"sources":[{"k":"web","label":"Tompkins County Workers’ Center, “New Tompkins County Living Wage Figures Announced”","sub":"News and public record","href":"https://www.tcworkerscenter.org/2026/04/wednesday-4-8-new-tompkins-county-living-wage-figures-announced/"},{"k":"web","label":"Alternatives FCU, “Tompkins County living wage updated, now $25.08/hour”","sub":"News and public record","href":"https://www.alternatives.org/tompkins-county-living-wage-updated-now-25-08-hour/"}],"thumb":null,"note":null},{"id":"min-wage-study","date":"2026-09-04","sort":"2026-09-04","year":2026,"label":"March–September 2026","era":"now","title":"The Tompkins County Minimum Wage Study","summary":"The ILR Co-Lab team holds eight public convenings and six focus groups, gathers over 100 surveys and 11 testimonies, and releases its report on September 4.","body":["Findings were shared at a public convening at the Tompkins County Public Library on August 27. The County Legislature took up the report in September. Ian Greer, David Bateman, Wen Li Thian, Matt Vidal and Adolfho Romero wrote it."],"themes":["wages","politics"],"orgs":["gov","students","tcwc"],"sources":[{"k":"site","label":"Tompkins County Minimum Wage Study (update on this site)","sub":"Elsewhere on this site","href":"../../updates/tompkins-minimum-wage-study.html"}],"thumb":null,"note":null}]};
